/* Official styles outside the restored dashboard. */
:root:where(:not(.app-shell, .app-shell *)){
  color-scheme: dark;
  --bg: #030816;
  --surface: #07152c;
  --surface-strong: #0b1d3c;
  --surface-soft: #10294e;
  --line: rgba(151, 200, 255, .11);
  --line-strong: rgba(151, 200, 255, .21);
  --text: #f5f9ff;
  --muted: #8192ac;
  --muted-strong: #b5c4d9;
  --accent: #48d7ff;
  --accent-ink: #001820;
  --accent-soft: rgba(72, 215, 255, .14);
  --page-gradient: radial-gradient(circle at 12% -10%, rgba(27, 112, 255, .36), transparent 34rem), radial-gradient(circle at 88% 4%, rgba(36, 214, 255, .17), transparent 31rem), linear-gradient(145deg, #071735 0%, #030816 48%, #06122b 100%);
  --card-gradient: linear-gradient(145deg, rgba(13, 34, 69, .96), rgba(5, 17, 39, .96));
  --market-gradient: radial-gradient(circle at 88% 18%, rgba(72, 215, 255, .17), transparent 45%), linear-gradient(135deg, #0d2854 0%, #07172f 58%, #061126 100%);
  --dock-gradient: linear-gradient(120deg, rgba(13, 34, 69, .88), rgba(6, 20, 44, .84));
  --floating-surface: rgba(7, 21, 44, .97);
  --dialog-gradient: linear-gradient(145deg, #0d2347, #06142d);
  --up: #39e58c;
  --up-soft: rgba(57, 229, 140, .15);
  --down: #ff5f70;
  --down-soft: rgba(255, 95, 112, .15);
  --radius: 18px;
  --shadow: 0 24px 65px rgba(0, 4, 18, .36);
  font-family: Inter, ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}
:root[data-theme="black"]:where(:not(.app-shell, .app-shell *)){
  --bg: #030405;
  --surface: #090c11;
  --surface-strong: #10151d;
  --surface-soft: #181f2a;
  --line: rgba(255, 255, 255, .09);
  --line-strong: rgba(255, 255, 255, .17);
  --text: #f7f9fc;
  --muted: #7f8997;
  --muted-strong: #b7bfca;
  --accent: #5ce1ff;
  --accent-ink: #00181d;
  --accent-soft: rgba(92, 225, 255, .11);
  --page-gradient: radial-gradient(circle at 50% -18%, rgba(28, 75, 102, .30), transparent 35rem), linear-gradient(145deg, #090d13 0%, #030405 58%, #080b10 100%);
  --card-gradient: linear-gradient(145deg, rgba(16, 21, 29, .98), rgba(7, 10, 15, .98));
  --market-gradient: radial-gradient(circle at 88% 18%, rgba(92, 225, 255, .12), transparent 45%), linear-gradient(135deg, #141c28 0%, #090d14 70%);
  --dock-gradient: linear-gradient(120deg, rgba(18, 24, 33, .94), rgba(8, 11, 16, .92));
  --floating-surface: rgba(10, 14, 21, .98);
  --dialog-gradient: linear-gradient(145deg, #121923, #080b11);
}
:root[data-theme="light"]:where(:not(.app-shell, .app-shell *)){
  color-scheme: light;
  --bg: #eef5ff;
  --surface: #ffffff;
  --surface-strong: #f5f9ff;
  --surface-soft: #e8f1fb;
  --line: rgba(17, 53, 91, .10);
  --line-strong: rgba(17, 53, 91, .20);
  --text: #10233b;
  --muted: #657991;
  --muted-strong: #41566f;
  --accent: #007da5;
  --accent-ink: #ffffff;
  --accent-soft: rgba(0, 125, 165, .10);
  --up: #087d4c;
  --up-soft: rgba(8, 125, 76, .12);
  --down: #d33d50;
  --down-soft: rgba(211, 61, 80, .11);
  --page-gradient: radial-gradient(circle at 12% -8%, rgba(64, 161, 255, .20), transparent 34rem), radial-gradient(circle at 88% 2%, rgba(0, 193, 226, .12), transparent 30rem), linear-gradient(145deg, #f8fbff 0%, #edf5ff 52%, #f5faff 100%);
  --card-gradient: linear-gradient(145deg, rgba(255, 255, 255, .98), rgba(244, 249, 255, .98));
  --market-gradient: radial-gradient(circle at 88% 18%, rgba(0, 161, 203, .13), transparent 45%), linear-gradient(135deg, #ffffff 0%, #edf7ff 68%, #f8fbff 100%);
  --dock-gradient: linear-gradient(120deg, rgba(255, 255, 255, .94), rgba(239, 247, 255, .92));
  --floating-surface: rgba(255, 255, 255, .98);
  --dialog-gradient: linear-gradient(145deg, #ffffff, #eff7ff);
  --shadow: 0 22px 58px rgba(32, 75, 120, .12);
}
*:where(:not(.app-shell, .app-shell *)){ box-sizing: border-box; }
html:where(:not(.app-shell, .app-shell *)){ scroll-behavior: smooth; }
body:where(:not(.app-shell, .app-shell *)){
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background: var(--page-gradient), var(--bg);
  background-attachment: fixed;
  color: var(--text);
  font-size: 16px;
  line-height: 1.5;
}
button:where(:not(.app-shell, .app-shell *)),
input:where(:not(.app-shell, .app-shell *)){ font: inherit; }
button:where(:not(.app-shell, .app-shell *)){ color: inherit; }
button:where(:not(.app-shell, .app-shell *)),
a:where(:not(.app-shell, .app-shell *)){ -webkit-tap-highlight-color: transparent; }
svg:where(:not(.app-shell, .app-shell *)){ display: block; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.app-shell:where(:not(.app-shell, .app-shell *)){ width: min(1600px, calc(100% - clamp(20px, 3vw, 52px))); margin: 0 auto; }
.topbar:where(:not(.app-shell, .app-shell *)){
  position: relative;
  z-index: 10;
  min-height: 78px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  border-bottom: 1px solid var(--line);
}
.brand:where(:not(.app-shell, .app-shell *)){ display: inline-flex; align-items: center; gap: 11px; color: var(--text); text-decoration: none; font-size: 1rem; letter-spacing: -.02em; }
.brand strong:where(:not(.app-shell, .app-shell *)){ font-weight: 800; }
.brand-mark:where(:not(.app-shell, .app-shell *)){
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: var(--accent);
  color: var(--accent-ink);
  font-weight: 900;
  box-shadow: 0 0 24px var(--accent-soft);
}
.topbar-tools:where(:not(.app-shell, .app-shell *)){ display: grid; justify-items: end; gap: 4px; padding: 9px 0 7px; }
.topbar-actions:where(:not(.app-shell, .app-shell *)){ display: flex; align-items: center; gap: 8px; }
.header-updated:where(:not(.app-shell, .app-shell *)){ color: var(--muted); font-size: .62rem; font-weight: 650; letter-spacing: .02em; }
.header-updated b:where(:not(.app-shell, .app-shell *)){ color: var(--muted-strong); font-weight: 750; font-variant-numeric: tabular-nums; }
.connection:where(:not(.app-shell, .app-shell *)){
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 38px;
  padding: 0 13px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--muted-strong);
  font-size: .78rem;
  font-weight: 700;
}
.connection i:where(:not(.app-shell, .app-shell *)),
.live-tag i:where(:not(.app-shell, .app-shell *)){ width: 7px; height: 7px; border-radius: 50%; background: #f0aa39; box-shadow: 0 0 0 4px rgba(240, 170, 57, .12); }
.connection.online i:where(:not(.app-shell, .app-shell *)),
.live-tag i:where(:not(.app-shell, .app-shell *)){ background: var(--up); box-shadow: 0 0 0 4px var(--up-soft); }
.connection.offline i:where(:not(.app-shell, .app-shell *)){ background: var(--down); box-shadow: 0 0 0 4px var(--down-soft); }
.icon-button:where(:not(.app-shell, .app-shell *)){
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--surface);
  cursor: pointer;
  transition: border-color .2s, background .2s, transform .2s;
}
.icon-button svg:where(:not(.app-shell, .app-shell *)){ width: 18px; }
.icon-button:hover:where(:not(.app-shell, .app-shell *)){ border-color: var(--line-strong); background: var(--surface-soft); }
.icon-button:active:where(:not(.app-shell, .app-shell *)){ transform: scale(.95); }
#themeButton:where(:not(.app-shell, .app-shell *)){ position: relative; }
#themeButton:where(:not(.app-shell, .app-shell *))::after{ content: ""; position: absolute; right: 5px; bottom: 5px; width: 6px; height: 6px; border: 1px solid var(--surface); border-radius: 50%; background: #3aa9ff; box-shadow: 0 0 7px rgba(58,169,255,.75); }
#themeButton[data-theme="black"]:where(:not(.app-shell, .app-shell *))::after{ background: #8792a2; box-shadow: 0 0 7px rgba(255,255,255,.35); }
#themeButton[data-theme="light"]:where(:not(.app-shell, .app-shell *))::after{ background: #ffffff; border-color: #7c8da2; box-shadow: 0 0 7px rgba(36,116,180,.35); }
.theme-control:where(:not(.app-shell, .app-shell *)){ position: relative; }
.theme-picker:where(:not(.app-shell, .app-shell *)){
  position: absolute;
  z-index: 12;
  top: calc(100% + 12px);
  right: 0;
  width: 168px;
  display: grid;
  gap: 5px;
  padding: 8px;
  border: 1px solid var(--line-strong);
  border-radius: 13px;
  background: var(--floating-surface);
  box-shadow: 0 22px 55px rgba(0, 4, 18, .38);
  opacity: 0;
  pointer-events: none;
  transform: translateY(-8px) scale(.98);
  transform-origin: top right;
  transition: opacity .18s, transform .18s;
  backdrop-filter: blur(18px);
}
.theme-control.open .theme-picker:where(:not(.app-shell, .app-shell *)){ opacity: 1; pointer-events: auto; transform: translateY(0) scale(1); }
.theme-picker button:where(:not(.app-shell, .app-shell *)){ display: grid; grid-template-columns: 24px 1fr; align-items: center; gap: 9px; min-height: 39px; padding: 0 9px; border: 1px solid transparent; border-radius: 9px; background: transparent; color: var(--muted-strong); text-align: left; font-size: .76rem; font-weight: 750; cursor: pointer; }
.theme-picker button:hover:where(:not(.app-shell, .app-shell *)),
.theme-picker button.active:where(:not(.app-shell, .app-shell *)){ border-color: var(--line); background: var(--surface-soft); color: var(--text); }
.theme-swatch:where(:not(.app-shell, .app-shell *)){ width: 23px; height: 23px; border: 1px solid rgba(255,255,255,.18); border-radius: 7px; }
.theme-swatch.navy:where(:not(.app-shell, .app-shell *)){ background: linear-gradient(145deg, #1762bd, #06142d); }
.theme-swatch.black:where(:not(.app-shell, .app-shell *)){ background: linear-gradient(145deg, #29313d, #050607); }
.theme-swatch.light:where(:not(.app-shell, .app-shell *)){ border-color: rgba(17,53,91,.16); background: linear-gradient(145deg, #ffffff, #d9edff); }
.header-search:where(:not(.app-shell, .app-shell *)){ position: relative; display: flex; align-items: center; }
.header-search .search-panel:where(:not(.app-shell, .app-shell *)){
  position: absolute;
  z-index: 12;
  top: calc(100% + 12px);
  right: 0;
  width: min(410px, calc(100vw - 24px));
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
  padding: 10px;
  border: 1px solid var(--line-strong);
  border-radius: 14px;
  background: var(--floating-surface);
  box-shadow: 0 22px 55px rgba(0, 4, 18, .56);
  opacity: 0;
  pointer-events: none;
  transform: translateY(-8px) scale(.98);
  transform-origin: top right;
  transition: opacity .2s, transform .2s;
  backdrop-filter: blur(18px);
}
.header-search.open .search-panel:where(:not(.app-shell, .app-shell *)){ opacity: 1; pointer-events: auto; transform: translateY(0) scale(1); }
.search-panel input:where(:not(.app-shell, .app-shell *)){
  min-width: 0;
  min-height: 42px;
  padding: 0 13px;
  border: 1px solid var(--line-strong);
  border-radius: 10px;
  outline: none;
  background: var(--surface-strong);
  color: var(--text);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: .82rem;
}
.search-panel input:focus:where(:not(.app-shell, .app-shell *)){ border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
.search-panel button:where(:not(.app-shell, .app-shell *)){
  min-height: 42px;
  padding: 0 15px;
  border: 0;
  border-radius: 10px;
  background: var(--accent);
  color: var(--accent-ink);
  font-weight: 850;
  cursor: pointer;
}
.search-panel button:disabled:where(:not(.app-shell, .app-shell *)){ opacity: .55; cursor: wait; }
main:where(:not(.app-shell, .app-shell *)){ padding: clamp(18px, 2.2vw, 30px) 0 clamp(28px, 3vw, 44px); }
.wallet-dock:where(:not(.app-shell, .app-shell *)){
  display: block;
  margin-bottom: 18px;
  padding: 11px 13px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--dock-gradient);
  box-shadow: var(--shadow);
  backdrop-filter: blur(18px);
}
.saved-wallets:where(:not(.app-shell, .app-shell *)){ min-width: 0; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 12px; }
.wallet-dock-title:where(:not(.app-shell, .app-shell *)){ min-width: 88px; }
.wallet-dock-title span:where(:not(.app-shell, .app-shell *)){ display: block; color: var(--muted); font-size: .68rem; font-weight: 850; letter-spacing: .09em; text-transform: uppercase; }
.wallet-dock-title strong:where(:not(.app-shell, .app-shell *)){ display: block; margin-top: 2px; color: var(--muted-strong); font-size: .72rem; }
.wallet-dock-title small:where(:not(.app-shell, .app-shell *)){ display: block; margin-top: 2px; color: var(--muted); font-size: .66rem; white-space: nowrap; }
.wallet-dock-spacer:where(:not(.app-shell, .app-shell *)){ min-width: 0; }
.wallet-chips:where(:not(.app-shell, .app-shell *)){ min-width: 0; display: flex; gap: 7px; overflow-x: auto; scrollbar-width: none; }
.wallet-chips:where(:not(.app-shell, .app-shell *))::-webkit-scrollbar{ display: none; }
.wallet-chip:where(:not(.app-shell, .app-shell *)){
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 38px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: rgba(255,255,255,.025);
  color: var(--muted-strong);
  cursor: pointer;
}
.wallet-chip:hover:where(:not(.app-shell, .app-shell *)){ border-color: var(--line-strong); }
.wallet-chip.active:where(:not(.app-shell, .app-shell *)){ border-color: color-mix(in srgb, var(--accent) 58%, transparent); background: var(--accent-soft); color: var(--text); }
.wallet-chip i:where(:not(.app-shell, .app-shell *)){ width: 7px; height: 7px; border-radius: 50%; background: var(--muted); }
.wallet-chip.active i:where(:not(.app-shell, .app-shell *)){ background: var(--accent); box-shadow: 0 0 10px var(--accent); }
.wallet-chip b:where(:not(.app-shell, .app-shell *)){ font-size: .78rem; }
.wallet-chip small:where(:not(.app-shell, .app-shell *)){ color: var(--muted); font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .66rem; }
.wallet-empty:where(:not(.app-shell, .app-shell *)){ color: var(--muted); font-size: .78rem; white-space: nowrap; }
.manage-button:where(:not(.app-shell, .app-shell *)),
.refresh-button:where(:not(.app-shell, .app-shell *)){
  min-height: 38px;
  padding: 0 13px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--surface-soft);
  color: var(--text);
  font-size: .78rem;
  font-weight: 750;
  cursor: pointer;
}
.manage-button:hover:where(:not(.app-shell, .app-shell *)),
.refresh-button:hover:where(:not(.app-shell, .app-shell *)){ border-color: var(--line-strong); filter: brightness(1.08); }
.refresh-button:disabled:where(:not(.app-shell, .app-shell *)){ opacity: .55; cursor: wait; }
.wallet-dock-actions:where(:not(.app-shell, .app-shell *)){ display: inline-flex; align-items: center; gap: 7px; }
.refresh-button:where(:not(.app-shell, .app-shell *)){ display: inline-flex; align-items: center; gap: 8px; }
.refresh-icon:where(:not(.app-shell, .app-shell *)){ width: 38px; min-height: 38px; justify-content: center; padding: 0; border-radius: 10px; }
.refresh-button svg:where(:not(.app-shell, .app-shell *)){ width: 15px; }
.refresh-button.loading svg:where(:not(.app-shell, .app-shell *)){ animation: spin .8s linear infinite; }
.account-board:where(:not(.app-shell, .app-shell *)){
  margin-bottom: clamp(10px, 1.2vw, 16px);
  padding: clamp(12px, 1.35vw, 20px);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--dock-gradient);
  box-shadow: var(--shadow);
  backdrop-filter: blur(18px);
}
.account-board[hidden]:where(:not(.app-shell, .app-shell *)){ display: none; }
.account-board-heading:where(:not(.app-shell, .app-shell *)){ display: flex; align-items: end; justify-content: space-between; gap: clamp(10px, 1.5vw, 20px); margin-bottom: clamp(10px, 1.2vw, 15px); }
.account-board-heading h1:where(:not(.app-shell, .app-shell *)){ margin: 3px 0 0; font-size: clamp(1.02rem, 1.45vw, 1.3rem); line-height: 1.15; letter-spacing: -.035em; }
.account-board-heading > small:where(:not(.app-shell, .app-shell *)){ color: var(--muted); font-size: .7rem; font-weight: 700; text-align: right; }
.wallet-card-grid:where(:not(.app-shell, .app-shell *)){ display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: clamp(8px, .9vw, 14px); align-items: stretch; }
.wallet-summary-card:where(:not(.app-shell, .app-shell *)){
  min-width: 0;
  min-height: clamp(164px, 13vw, 206px);
  height: 100%;
  padding: clamp(12px, 1.15vw, 17px);
  border: 1px solid var(--line);
  border-radius: 14px;
  background: color-mix(in srgb, var(--surface) 88%, transparent);
  display: flex;
  flex-direction: column;
  color: var(--text);
  text-align: left;
  cursor: pointer;
  transition: transform .18s, border-color .18s, background .18s, box-shadow .18s;
}
.wallet-summary-card:hover:where(:not(.app-shell, .app-shell *)){ transform: translateY(-2px); border-color: var(--line-strong); background: color-mix(in srgb, var(--surface-strong) 90%, transparent); }
.wallet-summary-card:active:where(:not(.app-shell, .app-shell *)){ transform: translateY(0) scale(.99); }
.wallet-summary-card.active:where(:not(.app-shell, .app-shell *)){ border-color: color-mix(in srgb, var(--accent) 58%, transparent); background: color-mix(in srgb, var(--accent-soft) 72%, var(--surface)); box-shadow: 0 0 0 1px var(--accent-soft), var(--shadow); }
.wallet-card-top:where(:not(.app-shell, .app-shell *)){ display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.wallet-card-name:where(:not(.app-shell, .app-shell *)){ min-width: 0; overflow: hidden; font-size: clamp(.74rem, .88vw, .88rem); font-weight: 850; text-overflow: ellipsis; white-space: nowrap; }
.wallet-card-live:where(:not(.app-shell, .app-shell *)){ display: inline-flex; align-items: center; gap: 5px; flex: 0 0 auto; color: var(--muted); font-size: clamp(.53rem, .62vw, .64rem); font-weight: 800; text-transform: uppercase; letter-spacing: .04em; }
.wallet-card-live i:where(:not(.app-shell, .app-shell *)){ width: 6px; height: 6px; border-radius: 50%; background: var(--muted); }
.wallet-summary-card.synced .wallet-card-live:where(:not(.app-shell, .app-shell *)){ color: var(--up); }
.wallet-summary-card.synced .wallet-card-live i:where(:not(.app-shell, .app-shell *)){ background: var(--up); box-shadow: 0 0 0 3px var(--up-soft); }
.wallet-summary-card.active .wallet-card-live:where(:not(.app-shell, .app-shell *)){ color: var(--accent); }
.wallet-summary-card.active .wallet-card-live i:where(:not(.app-shell, .app-shell *)){ background: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
.wallet-card-address:where(:not(.app-shell, .app-shell *)){ display: block; margin-top: 4px; overflow: hidden; color: var(--muted); font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: clamp(.56rem, .64vw, .66rem); text-overflow: ellipsis; white-space: nowrap; }
.wallet-card-total:where(:not(.app-shell, .app-shell *)){ display: block; margin-top: clamp(12px, 1.35vw, 18px); overflow: hidden; font-size: clamp(1.02rem, 1.75vw, 1.58rem); font-weight: 880; letter-spacing: -.035em; text-overflow: ellipsis; white-space: nowrap; font-variant-numeric: tabular-nums; }
.wallet-card-worth:where(:not(.app-shell, .app-shell *)){ display: block; margin-top: 3px; color: var(--muted-strong); font-size: clamp(.66rem, .76vw, .79rem); font-weight: 720; font-variant-numeric: tabular-nums; }
.wallet-card-metrics:where(:not(.app-shell, .app-shell *)){ display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: clamp(4px, .55vw, 8px); margin-top: clamp(10px, 1vw, 14px); padding-top: clamp(8px, .85vw, 12px); border-top: 1px solid var(--line); }
.wallet-card-metrics span:where(:not(.app-shell, .app-shell *)){ display: block; color: var(--muted); font-size: clamp(.5rem, .56vw, .59rem); font-weight: 760; text-transform: uppercase; letter-spacing: .025em; }
.wallet-card-metrics strong:where(:not(.app-shell, .app-shell *)){ display: block; margin-top: 3px; overflow: hidden; color: var(--muted-strong); font-size: clamp(.62rem, .7vw, .74rem); text-overflow: ellipsis; white-space: nowrap; font-variant-numeric: tabular-nums; }
.wallet-card-updated:where(:not(.app-shell, .app-shell *)){ display: block; margin-top: auto; padding-top: clamp(8px, .8vw, 11px); color: var(--muted); font-size: clamp(.54rem, .61vw, .63rem); }
.wallet-summary-card.cached-card .wallet-card-live:where(:not(.app-shell, .app-shell *)){ color: var(--muted); }
.wallet-summary-card.cached-card .wallet-card-live i:where(:not(.app-shell, .app-shell *)){ background: var(--muted); }
.wallet-summary-card.loading-card .wallet-card-total:where(:not(.app-shell, .app-shell *)),
.wallet-summary-card.loading-card .wallet-card-worth:where(:not(.app-shell, .app-shell *)),
