/* v15.98.15 — fixed-geometry selective per-digit odometer for Home + Dashboard + Live View.
   Every digit keeps a fixed tabular 1ch lane, including unchanged digits.
   Animated markup and final plain text therefore have identical geometry. */
.number-roll-host,
.number-roll-text {
  white-space: nowrap;
  font-variant-numeric: tabular-nums lining-nums;
  font-feature-settings: "tnum" 1, "lnum" 1;
}
.number-roll-text {
  display: inline;
  font: inherit;
  font-size: 1em;
  font-weight: inherit;
  letter-spacing: inherit;
  line-height: inherit;
  vertical-align: baseline;
}
/* Rolling values may still flash color, but never add a text glow: the glow
   made the glyph silhouette look temporarily larger even though font-size
   itself was unchanged. */
.number-roll-host.value-change-up,
.number-roll-host.value-change-down,
.number-roll-host.entry-value-up,
.number-roll-host.entry-value-down,
.number-roll-host.focus-value-up,
.number-roll-host.focus-value-down {
  text-shadow: none !important;
}
.number-roll-static-digit,
.number-roll-digit {
  width: 1ch;
  min-width: 1ch;
  max-width: 1ch;
  box-sizing: border-box;
  vertical-align: baseline;
  line-height: inherit;
  white-space: nowrap;
  text-align: center;
}
.number-roll-static-digit {
  display: inline-block;
}
.number-roll-digit {
  display: inline-grid;
  grid-template-columns: 1fr;
  grid-template-rows: 1fr;
  overflow: hidden;
  isolation: isolate;
}
.number-roll-digit-layer {
  grid-column: 1;
  grid-row: 1;
  width: 1ch;
  min-width: 1ch;
  max-width: 1ch;
  font: inherit;
  font-size: 1em;
  line-height: inherit;
  text-align: center;
  white-space: nowrap;
  will-change: transform, opacity;
}
.number-roll-up .number-roll-old {
  animation: numberRollOldUp .46s cubic-bezier(.22,.72,.18,1) both;
}
.number-roll-up .number-roll-new {
  animation: numberRollNewUp .46s cubic-bezier(.22,.72,.18,1) both;
}
.number-roll-down .number-roll-old {
  animation: numberRollOldDown .46s cubic-bezier(.22,.72,.18,1) both;
}
.number-roll-down .number-roll-new {
  animation: numberRollNewDown .46s cubic-bezier(.22,.72,.18,1) both;
}
@keyframes numberRollOldUp {
  from { transform: translate3d(0,0,0); opacity: 1; }
  to { transform: translate3d(0,-115%,0); opacity: .18; }
}
@keyframes numberRollNewUp {
  from { transform: translate3d(0,115%,0); opacity: .18; }
  to { transform: translate3d(0,0,0); opacity: 1; }
}
@keyframes numberRollOldDown {
  from { transform: translate3d(0,0,0); opacity: 1; }
  to { transform: translate3d(0,115%,0); opacity: .18; }
}
@keyframes numberRollNewDown {
  from { transform: translate3d(0,-115%,0); opacity: .18; }
  to { transform: translate3d(0,0,0); opacity: 1; }
}
