  --floating-surface: rgba(255, 255, 255, .985);
  --dialog-gradient: linear-gradient(145deg, #ffffff, #f0f6fb);
  --card-orb: rgba(10, 139, 177, .045);
  --card-orb-alt: rgba(67, 132, 220, .035);
  --card-inner-highlight: rgba(255, 255, 255, .72);
  --card-shadow-accent: rgba(36, 105, 164, .055);
  --shadow: 0 18px 46px rgba(35, 78, 115, .10), 0 5px 16px rgba(48, 88, 122, .055);
}
/* Superfici: bordo più fine, highlight interno e ombra meno piatta. */
.data-card:where(:not(.app-shell, .app-shell *)),
.wallet-dock:where(:not(.app-shell, .app-shell *)),
.aggregate-strip:where(:not(.app-shell, .app-shell *)),
.wallet-mini:where(:not(.app-shell, .app-shell *)),
.icon-button:where(:not(.app-shell, .app-shell *)),
.theme-picker:where(:not(.app-shell, .app-shell *)),
.header-search .search-panel:where(:not(.app-shell, .app-shell *)),
.wallet-dialog:where(:not(.app-shell, .app-shell *)){
  box-shadow: var(--shadow), inset 0 1px 0 var(--card-inner-highlight);
}
.data-card:where(:not(.app-shell, .app-shell *)){
  border-color: color-mix(in srgb, var(--line-strong) 62%, var(--line));
}
/* Un bagliore molto leggero, ispirato alla card INJ/USDT, anche sulle altre card. */
.data-card:not(.market-card):where(:not(.app-shell, .app-shell *))::before{
  content: "";
  position: absolute;
  z-index: 0;
  width: clamp(150px, 16vw, 250px);
  height: clamp(150px, 16vw, 250px);
  top: clamp(-118px, -8vw, -72px);
  right: clamp(-105px, -6vw, -62px);
  border-radius: 50%;
  pointer-events: none;
  background:
    radial-gradient(circle at 42% 42%, var(--card-orb), transparent 62%),
    radial-gradient(circle at 65% 68%, var(--card-orb-alt), transparent 58%);
  opacity: .9;
}
.data-card > *:where(:not(.app-shell, .app-shell *)){ position: relative; z-index: 1; }
/* Variamo appena la posizione per evitare l'effetto copia/incolla. */
.metric-card:nth-child(even):where(:not(.app-shell, .app-shell *))::before{ top: auto; bottom: -105px; right: -78px; }
.metric-card:nth-child(3):where(:not(.app-shell, .app-shell *))::before{ right: auto; left: -92px; top: -96px; }
.reward-tracker-card:where(:not(.app-shell, .app-shell *))::before{ width: 320px; height: 320px; right: -170px; top: -180px; opacity: .72; }
.target-card:where(:not(.app-shell, .app-shell *))::before{ width: 270px; height: 270px; right: -140px; bottom: -170px; top: auto; opacity: .66; }
.validator-card:where(:not(.app-shell, .app-shell *))::before{ width: 340px; height: 340px; right: -180px; top: -220px; opacity: .52; }
.worth-card:where(:not(.app-shell, .app-shell *))::before{ width: 280px; height: 280px; right: -142px; top: -152px; opacity: .78; }
/* La prima card resta la più caratteristica, ma il cerchio è più raffinato. */
.market-card:where(:not(.app-shell, .app-shell *))::before{
  width: 250px;
  height: 250px;
  right: -112px;
  bottom: -126px;
  background:
    radial-gradient(circle at 42% 42%, color-mix(in srgb, var(--accent) 14%, transparent), transparent 56%),
    radial-gradient(circle at 68% 68%, var(--card-orb-alt), transparent 62%);
  filter: blur(1px);
  opacity: .92;
}
/* Accenti sottili per distinguere i gruppi senza aggiungere colori invadenti. */
.apr-card:where(:not(.app-shell, .app-shell *)){
  border-color: color-mix(in srgb, var(--accent) 27%, var(--line));
  background:
    radial-gradient(circle at 100% 0%, color-mix(in srgb, var(--accent) 7%, transparent), transparent 38%),
    var(--card-gradient);
}
.milestone-block:where(:not(.app-shell, .app-shell *)),
.target-stats > div:where(:not(.app-shell, .app-shell *)),
.reward-rate-grid > div:where(:not(.app-shell, .app-shell *)),
.yield-grid > div:where(:not(.app-shell, .app-shell *)){
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--card-inner-highlight) 72%, transparent);
}
.aggregate-strip:where(:not(.app-shell, .app-shell *)){
  background: color-mix(in srgb, var(--line-strong) 58%, transparent);
  border-color: color-mix(in srgb, var(--line-strong) 68%, var(--line));
}
.aggregate-heading:where(:not(.app-shell, .app-shell *)){
  position: relative;
  overflow: hidden;
}
.aggregate-heading:where(:not(.app-shell, .app-shell *))::after{
  content: "";
  position: absolute;
  width: 120px;
  height: 120px;
  right: -62px;
  top: -64px;
  border-radius: 50%;
  background: radial-gradient(circle, var(--card-orb), transparent 68%);
  pointer-events: none;
}
.wallet-dock:where(:not(.app-shell, .app-shell *)){
  border-color: color-mix(in srgb, var(--line-strong) 58%, var(--line));
}
.wallet-mini:where(:not(.app-shell, .app-shell *)){
  background:
    radial-gradient(circle at 110% -15%, var(--card-orb), transparent 42%),
    color-mix(in srgb, var(--surface) 90%, transparent);
}
.wallet-mini.active:where(:not(.app-shell, .app-shell *)){
  border-color: color-mix(in srgb, var(--accent) 50%, var(--line));
  background:
    radial-gradient(circle at 108% -8%, color-mix(in srgb, var(--accent) 10%, transparent), transparent 48%),
    color-mix(in srgb, var(--accent-soft) 52%, var(--surface));
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent) 8%, transparent), var(--shadow), inset 0 1px 0 var(--card-inner-highlight);
}
/* Topbar e controlli più coerenti col tema. */
.topbar:where(:not(.app-shell, .app-shell *)){
  border-bottom-color: color-mix(in srgb, var(--line-strong) 55%, transparent);
}
.brand-mark:where(:not(.app-shell, .app-shell *)){
  background: linear-gradient(145deg, color-mix(in srgb, var(--accent) 88%, white 12%), var(--accent));
  box-shadow: 0 0 26px color-mix(in srgb, var(--accent) 18%, transparent), inset 0 1px 0 rgba(255,255,255,.22);
}
.icon-button:where(:not(.app-shell, .app-shell *)){
  background: color-mix(in srgb, var(--surface) 93%, transparent);
}
.icon-button:hover:where(:not(.app-shell, .app-shell *)){
  border-color: color-mix(in srgb, var(--accent) 24%, var(--line-strong));
  background: color-mix(in srgb, var(--surface-strong) 88%, var(--surface));
}
/* Swatch aggiornati per far capire davvero i tre look. */
.theme-swatch.navy:where(:not(.app-shell, .app-shell *)){
  background:
    radial-gradient(circle at 74% 24%, rgba(98, 231, 255, .58), transparent 25%),
    radial-gradient(circle at 18% 80%, rgba(145, 79, 255, .40), transparent 34%),
    linear-gradient(145deg, #14366f, #090a20 70%);
}
.theme-swatch.black:where(:not(.app-shell, .app-shell *)){
  background:
    radial-gradient(circle at 72% 28%, rgba(121, 222, 245, .20), transparent 28%),
    linear-gradient(145deg, #252c34, #050607 72%);
}
.theme-swatch.light:where(:not(.app-shell, .app-shell *)){
  border-color: rgba(17,53,91,.14);
  background:
    radial-gradient(circle at 72% 28%, rgba(20, 151, 190, .18), transparent 28%),
    linear-gradient(145deg, #ffffff, #dcebf5 72%);
}
/* Tema chiaro: il vetro è più credibile con ombre e bordi più leggeri. */
:root[data-theme="light"] .data-card:where(:not(.app-shell, .app-shell *)),
:root[data-theme="light"] .wallet-dock:where(:not(.app-shell, .app-shell *)),
:root[data-theme="light"] .wallet-mini:where(:not(.app-shell, .app-shell *)),
:root[data-theme="light"] .aggregate-strip:where(:not(.app-shell, .app-shell *)){
  backdrop-filter: blur(14px) saturate(108%);
}
/* Nero: niente blu troppo acceso; l'accento resta quasi "ghiaccio". */
:root[data-theme="black"] .apr-card .metric-value:where(:not(.app-shell, .app-shell *)),
:root[data-theme="black"] .formula-pill:where(:not(.app-shell, .app-shell *)),
:root[data-theme="black"] .milestone-block strong:where(:not(.app-shell, .app-shell *)){
  color: #86dced;
}
/* Responsive: sugli schermi piccoli i glow diventano ancora più discreti. */
@media  (max-width: 820px) {.data-card:not(.market-card):where(:not(.app-shell, .app-shell *))::before{ opacity: .58; transform: scale(.86); transform-origin: top right; }
.market-card:where(:not(.app-shell, .app-shell *))::before{ opacity: .72; transform: scale(.9); transform-origin: bottom right; }
.reward-tracker-card:where(:not(.app-shell, .app-shell *))::before,
.target-card:where(:not(.app-shell, .app-shell *))::before,
.validator-card:where(:not(.app-shell, .app-shell *))::before{ opacity: .44; }}
@media  (max-width: 560px) {.data-card:where(:not(.app-shell, .app-shell *)),
.wallet-dock:where(:not(.app-shell, .app-shell *)),
.aggregate-strip:where(:not(.app-shell, .app-shell *)){ box-shadow: 0 14px 32px color-mix(in srgb, var(--bg) 72%, transparent), inset 0 1px 0 var(--card-inner-highlight); }}
/* v14.6 — Totale multi-wallet collassabile */
.aggregate-strip:where(:not(.app-shell, .app-shell *)){
  cursor: pointer;
  user-select: none;
  transition: border-color .2s ease, box-shadow .2s ease, background .2s ease;
}
.aggregate-strip:hover:where(:not(.app-shell, .app-shell *)){
  border-color: color-mix(in srgb, var(--accent) 30%, var(--line-strong));
}
.aggregate-strip:focus-visible:where(:not(.app-shell, .app-shell *)){
  outline: 2px solid color-mix(in srgb, var(--accent) 68%, transparent);
  outline-offset: 3px;
}
.aggregate-heading:where(:not(.app-shell, .app-shell *)){
  padding-right: clamp(42px, 4vw, 52px) !important;
}
.aggregate-chevron:where(:not(.app-shell, .app-shell *)){
  position: absolute;
  right: clamp(11px, 1vw, 15px);
  top: 50%;
  width: 27px;
  height: 27px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: color-mix(in srgb, var(--surface-soft) 78%, transparent);
  color: var(--muted-strong);
  transform: translateY(-50%);
  transition: transform .22s ease, background .2s ease, color .2s ease;
  pointer-events: none;
  z-index: 2;
}
.aggregate-chevron svg:where(:not(.app-shell, .app-shell *)){ width: 15px; height: 15px; }
.aggregate-strip:hover .aggregate-chevron:where(:not(.app-shell, .app-shell *)){
  background: var(--accent-soft);
  color: var(--text);
}
.aggregate-strip.collapsed:where(:not(.app-shell, .app-shell *)){
  grid-template-columns: 1fr !important;
  gap: 0;
}
.aggregate-strip.collapsed .aggregate-heading:where(:not(.app-shell, .app-shell *)){
  grid-column: 1 / -1;
  min-height: clamp(48px, 4vw, 56px) !important;
}
.aggregate-strip.collapsed .aggregate-metric:where(:not(.app-shell, .app-shell *)){
  display: none;
}
.aggregate-strip.collapsed .aggregate-chevron:where(:not(.app-shell, .app-shell *)){
  transform: translateY(-50%) rotate(-90deg);
}
.aggregate-strip.collapsed .aggregate-heading small:where(:not(.app-shell, .app-shell *)){
  margin-top: 2px;
}
@media  (max-width: 560px) {.aggregate-strip.collapsed .aggregate-heading:where(:not(.app-shell, .app-shell *)){
    min-height: 48px !important;
    padding-top: 7px !important;
    padding-bottom: 7px !important;
  }
.aggregate-chevron:where(:not(.app-shell, .app-shell *)){
    width: 25px;
    height: 25px;
    right: 9px;
  }}
/* =========================================================
   v14.7 — Header minimale: menu sx, titolo centro, ricerca dx
