.header-main-button:active:where(:not(.app-shell, .app-shell *)){ transform: scale(.95); }
.header-menu.open #menuButton:where(:not(.app-shell, .app-shell *)){ color: var(--accent); border-color: color-mix(in srgb, var(--accent) 34%, var(--line)); background: var(--accent-soft); }
.header-status-dot.connection:where(:not(.app-shell, .app-shell *)){
