}
.header-status-dot.connection span:where(:not(.app-shell, .app-shell *)){ position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.header-status-dot.connection i:where(:not(.app-shell, .app-shell *)){ width: 7px; height: 7px; margin: auto; }
.header-menu-panel:where(:not(.app-shell, .app-shell *)){
