/* =========================================================
   v14.10 — Aurora dinamica fluida
   Movimento solo compositing-friendly: transform + opacity.
   ========================================================= */
:root[data-theme="navy"]:where(:not(.app-shell, .app-shell *)){
  --aurora-cyan: rgba(87, 232, 255, .105);
  --aurora-mint: rgba(92, 255, 202, .085);
  --aurora-violet: rgba(150, 113, 255, .072);
  --page-gradient: linear-gradient(151deg, #07131a 0%, #020609 48%, #090b16 100%);
}
:root[data-theme="navy"] body:where(:not(.app-shell, .app-shell *)){
  position: relative;
  isolation: isolate;
  overflow-x: hidden;
  background: var(--page-gradient), var(--bg);
  background-attachment: scroll;
}
/* Due grandi livelli rasterizzati una volta e mossi solo via transform. */
:root[data-theme="navy"] body:where(:not(.app-shell, .app-shell *))::before,
:root[data-theme="navy"] body:where(:not(.app-shell, .app-shell *))::after{
  content: "";
  position: fixed;
  z-index: -1;
  inset: -22vmax;
  pointer-events: none;
  will-change: transform, opacity;
  transform: translate3d(0, 0, 0);
  backface-visibility: hidden;
}
:root[data-theme="navy"] body:where(:not(.app-shell, .app-shell *))::before{
  background:
    radial-gradient(ellipse 34% 24% at 24% 28%, var(--aurora-cyan), transparent 72%),
    radial-gradient(ellipse 30% 25% at 70% 18%, var(--aurora-mint), transparent 72%),
    radial-gradient(ellipse 31% 27% at 73% 76%, var(--aurora-violet), transparent 74%);
  opacity: .95;
  animation: auroraDriftPrimary 28s cubic-bezier(.45, 0, .55, 1) infinite alternate;
}
:root[data-theme="navy"] body:where(:not(.app-shell, .app-shell *))::after{
  background:
    radial-gradient(ellipse 28% 17% at 36% 65%, rgba(77, 211, 255, .055), transparent 73%),
    radial-gradient(ellipse 30% 18% at 61% 48%, rgba(97, 255, 204, .044), transparent 74%),
    radial-gradient(ellipse 26% 18% at 48% 22%, rgba(143, 108, 255, .048), transparent 74%);
  opacity: .75;
  animation: auroraDriftSecondary 36s cubic-bezier(.42, 0, .58, 1) infinite alternate;
}
@keyframes auroraDriftPrimary {
  0%   { transform: translate3d(-2.2%, -1.2%, 0) rotate(-1deg) scale(1.01); opacity: .80; }
  45%  { transform: translate3d(2.6%, 1.8%, 0) rotate(.8deg) scale(1.035); opacity: 1; }
  100% { transform: translate3d(-.4%, 3.0%, 0) rotate(1.5deg) scale(1.02); opacity: .88; }
}
@keyframes auroraDriftSecondary {
  0%   { transform: translate3d(2.8%, 1.4%, 0) rotate(1.2deg) scale(1.025); opacity: .60; }
  55%  { transform: translate3d(-2.0%, -2.0%, 0) rotate(-1deg) scale(1.045); opacity: .82; }
  100% { transform: translate3d(1.2%, -3.0%, 0) rotate(-1.6deg) scale(1.015); opacity: .68; }
}
/* La card principale respira appena: niente animazioni sulle altre card. */
:root[data-theme="navy"] .market-card:where(:not(.app-shell, .app-shell *))::before{
  will-change: transform, opacity;
  animation: auroraMarketBreath 12s ease-in-out infinite alternate;
}
@keyframes auroraMarketBreath {
  from { transform: translate3d(0, 0, 0) scale(1); opacity: .78; }
  to   { transform: translate3d(-7px, -5px, 0) scale(1.055); opacity: .94; }
}
/* Un accento luminoso lento sul wallet attivo, senza muovere il layout. */
:root[data-theme="navy"] .wallet-mini.active:where(:not(.app-shell, .app-shell *)){
  position: relative;
  overflow: hidden;
}
:root[data-theme="navy"] .wallet-mini.active:where(:not(.app-shell, .app-shell *))::after{
  content: "";
  position: absolute;
  inset: -65% -35%;
  pointer-events: none;
  background: linear-gradient(110deg, transparent 38%, rgba(161, 255, 239, .055) 49%, rgba(139, 201, 255, .045) 54%, transparent 65%);
  transform: translate3d(-32%, 0, 0) rotate(4deg);
  will-change: transform;
  animation: auroraWalletGlide 8s ease-in-out infinite;
}
:root[data-theme="navy"] .wallet-mini.active > *:where(:not(.app-shell, .app-shell *)){ position: relative; z-index: 1; }
@keyframes auroraWalletGlide {
  0%, 24% { transform: translate3d(-34%, 0, 0) rotate(4deg); }
  62%, 100% { transform: translate3d(34%, 0, 0) rotate(4deg); }
}
/* Su dispositivi più piccoli riduciamo i layer animati, non il frame-rate. */
@media  (max-width: 820px) {:root[data-theme="navy"] body:where(:not(.app-shell, .app-shell *))::before{ animation-duration: 34s; opacity: .82; }
:root[data-theme="navy"] body:where(:not(.app-shell, .app-shell *))::after{ animation-duration: 44s; opacity: .56; }
:root[data-theme="navy"] .market-card:where(:not(.app-shell, .app-shell *))::before{ animation: none; }
:root[data-theme="navy"] .wallet-mini.active:where(:not(.app-shell, .app-shell *))::after{ animation-duration: 11s; opacity: .68; }}
/* Rispetta le preferenze di accessibilità e azzera ogni movimento. */
@media  (prefers-reduced-motion: reduce) {:root[data-theme="navy"] body:where(:not(.app-shell, .app-shell *))::before,
:root[data-theme="navy"] body:where(:not(.app-shell, .app-shell *))::after,
:root[data-theme="navy"] .market-card:where(:not(.app-shell, .app-shell *))::before,
:root[data-theme="navy"] .wallet-mini.active:where(:not(.app-shell, .app-shell *))::after{
    animation: none !important;
    transform: none !important;
  }}
