  text-align: right;
  font-variant-numeric: tabular-nums;
}
.market-tf.positive .market-tf-meta em:where(:not(.app-shell, .app-shell *)){ color: var(--up); }
.market-tf.negative .market-tf-meta em:where(:not(.app-shell, .app-shell *)){ color: var(--down); }
.market-tf-track:where(:not(.app-shell, .app-shell *)){
  --tf-pos: 50%;
  --tf-open-pos: 50%;
  --tf-fill-start: 50%;
  --tf-fill-width: 0%;
  position: relative;
  height: 9px;
  overflow: visible;
  border-radius: 999px;
  background:
    linear-gradient(90deg,
      color-mix(in srgb, var(--down-soft) 31%, transparent),
      color-mix(in srgb, var(--surface-soft) 76%, transparent) 48%,
      color-mix(in srgb, var(--up-soft) 31%, transparent)),
    color-mix(in srgb, var(--surface-soft) 72%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--line) 76%, transparent);
}
.market-tf-track:where(:not(.app-shell, .app-shell *))::before,
.market-tf-track:where(:not(.app-shell, .app-shell *))::after{
  content: "";
  position: absolute;
  top: 50%;
  width: 2px;
  height: 5px;
  border-radius: 2px;
  background: color-mix(in srgb, var(--muted) 52%, transparent);
  transform: translateY(-50%);
}
.market-tf-track:where(:not(.app-shell, .app-shell *))::before{ left: 0; }
.market-tf-track:where(:not(.app-shell, .app-shell *))::after{ right: 0; }
.market-tf-fill:where(:not(.app-shell, .app-shell *)){
  position: absolute;
  z-index: 1;
  left: var(--tf-fill-start);
  top: 2.5px;
  width: var(--tf-fill-width);
  height: 4px;
  border-radius: 999px;
  background: var(--muted);
  opacity: .76;
  transition: left .72s cubic-bezier(.2,.8,.2,1), width .72s cubic-bezier(.2,.8,.2,1), background-color .25s, opacity .25s;
}
.market-tf-open-marker:where(:not(.app-shell, .app-shell *)){
  position: absolute;
  z-index: 2;
  left: var(--tf-open-pos);
  top: -3px;
  width: 2px;
  height: 15px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--text) 72%, var(--muted));
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--surface) 78%, transparent);
  transform: translateX(-50%);
  opacity: .76;
  transition: left .72s cubic-bezier(.2,.8,.2,1);
}
.market-tf-dot:where(:not(.app-shell, .app-shell *)){
  position: absolute;
  z-index: 3;
  left: var(--tf-pos);
  top: 50%;
  width: 9px;
  height: 9px;
  border: 2px solid var(--surface);
  border-radius: 50%;
  background: var(--muted);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--muted) 12%, transparent);
  transform: translate(-50%, -50%);
  transition: left .72s cubic-bezier(.2,.8,.2,1), background-color .25s, box-shadow .25s;
}
