.market-tf.negative .market-tf-dot:where(:not(.app-shell, .app-shell *)){ background: var(--down); }
.market-tf.positive .market-tf-dot:where(:not(.app-shell, .app-shell *)){ box-shadow: 0 0 0 3px var(--up-soft), 0 0 12px color-mix(in srgb, var(--up) 35%, transparent); }
.market-tf.negative .market-tf-dot:where(:not(.app-shell, .app-shell *)){ box-shadow: 0 0 0 3px var(--down-soft), 0 0 12px color-mix(in srgb, var(--down) 30%, transparent); }
