@media  (min-width: 821px) and (max-width: 1100px) {.metrics-grid:where(:not(.app-shell, .app-shell *)){ grid-template-columns: repeat(6, minmax(0, 1fr)); }
.metrics-grid > .data-card:nth-child(-n/**/+3):where(:not(.app-shell, .app-shell *)){ grid-column: span 2; }
.metrics-grid > .data-card:nth-child(n/**/+4):where(:not(.app-shell, .app-shell *)){ grid-column: span 3; }}
@media  (max-width: 820px) {.metrics-grid:where(:not(.app-shell, .app-shell *)){ grid-template-columns: 1fr; }}
/* v15.11 — Differenza compatta sulla destra */
.total-owned-card:where(:not(.app-shell, .app-shell *)){
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(12px, 1.2vw, 22px);
}
.owned-total-main:where(:not(.app-shell, .app-shell *)){ min-width: 0; }
.owned-total-main .metric-value:where(:not(.app-shell, .app-shell *)){ margin-top: 20px; }
.owned-total-main > small:where(:not(.app-shell, .app-shell *)){
  display: block;
  margin-top: 8px;
  color: var(--muted);
  font-size: .78rem;
}
.owned-total-difference:where(:not(.app-shell, .app-shell *)){
  display: inline-flex;
  align-items: center;
  justify-content: center;
  align-self: center;
  gap: 5px;
  min-width: 0;
  padding-left: clamp(8px, .8vw, 14px);
  color: var(--up);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.owned-total-plus:where(:not(.app-shell, .app-shell *)){
  color: var(--up);
  font-size: clamp(1rem, 1.25vw, 1.22rem);
  font-weight: 900;
  line-height: 1;
}
.owned-total-difference > strong:where(:not(.app-shell, .app-shell *)){
  max-width: 100%;
  overflow: hidden;
  color: var(--up);
  font-size: clamp(.88rem, 1.15vw, 1.06rem);
  font-weight: 850;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}
@media  (max-width: 520px) {.total-owned-card:where(:not(.app-shell, .app-shell *)){ grid-template-columns: minmax(0, 1fr) auto; gap: 9px; }
.owned-total-main .metric-value:where(:not(.app-shell, .app-shell *)){ margin-top: 14px; }
.owned-total-main > small:where(:not(.app-shell, .app-shell *)){ margin-top: 5px; font-size: .68rem; }
.owned-total-difference:where(:not(.app-shell, .app-shell *)){ padding-left: 6px; gap: 4px; }
.owned-total-plus:where(:not(.app-shell, .app-shell *)){ font-size: .94rem; }
.owned-total-difference > strong:where(:not(.app-shell, .app-shell *)){ font-size: .82rem; }}
/* v15.12 — prezzo medio e PnL */
.menu-average-price:where(:not(.app-shell, .app-shell *)){
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) auto;
  align-items: center;
  gap: 9px;
  min-height: 54px;
  padding: 7px 9px;
  border: 1px solid transparent;
  border-radius: 11px;
}
.menu-average-copy:where(:not(.app-shell, .app-shell *)){ min-width: 0; display: grid; gap: 1px; cursor: text; }
.menu-average-copy strong:where(:not(.app-shell, .app-shell *)){ color: var(--text); font-size: .78rem; font-weight: 800; }
.menu-average-copy small:where(:not(.app-shell, .app-shell *)){ overflow: hidden; color: var(--muted); font-size: .62rem; text-overflow: ellipsis; white-space: nowrap; }
.menu-average-input:where(:not(.app-shell, .app-shell *)){
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-width: 92px;
  padding: 0 8px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--surface-strong);
  color: var(--accent);
  font-size: .72rem;
  font-weight: 850;
}
.menu-average-input:focus-within:where(:not(.app-shell, .app-shell *)){ border-color: color-mix(in srgb, var(--accent) 55%, transparent); box-shadow: 0 0 0 3px var(--accent-soft); }
.menu-average-input input:where(:not(.app-shell, .app-shell *)){
  width: 68px;
  min-height: 34px;
  padding: 0;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--text);
  font-size: .76rem;
  font-weight: 800;
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.menu-average-input input:disabled:where(:not(.app-shell, .app-shell *)){ opacity: .45; }
.worth-performance-stack:where(:not(.app-shell, .app-shell *)){ display: flex; flex-wrap: wrap; align-items: center; gap: 6px; margin-top: 8px; }
.worth-performance-stack .worth-change:where(:not(.app-shell, .app-shell *)){ margin-top: 0; }
@media  (max-width: 520px) {.worth-performance-stack:where(:not(.app-shell, .app-shell *)){ display: grid; justify-items: start; gap: 5px; }
.menu-average-price:where(:not(.app-shell, .app-shell *)){ grid-template-columns: 32px minmax(0, 1fr) auto; }
.menu-average-input:where(:not(.app-shell, .app-shell *)){ min-width: 84px; }
.menu-average-input input:where(:not(.app-shell, .app-shell *)){ width: 60px; }}
/* =========================================================
   v15.13 — Temi nettamente distinti
   Aurora = boreale / teal + indaco / atmosferico
   Nero   = Obsidian OLED / monocromatico / minimale
   ========================================================= */
/* AURORA: più cromatico e riconoscibile, ma ancora elegante. */
:root[data-theme="navy"]:where(:not(.app-shell, .app-shell *)){
  --bg: #020708;
  --surface: #071515;
  --surface-strong: #0b1e1e;
  --surface-soft: #102a29;
  --line: rgba(153, 241, 224, .085);
  --line-strong: rgba(166, 242, 230, .17);
  --text: #f4fffc;
  --muted: #809c99;
  --muted-strong: #bed8d4;
  --accent: #7ef2d4;
  --accent-ink: #001812;
  --accent-soft: rgba(126, 242, 212, .10);
  --page-gradient: linear-gradient(150deg, #061519 0%, #020708 46%, #0c0a1a 100%);
  --card-gradient:
    radial-gradient(circle at 104% -8%, rgba(126, 242, 212, .060), transparent 34%),
    radial-gradient(circle at -8% 108%, rgba(120, 101, 255, .040), transparent 38%),
    linear-gradient(145deg, rgba(9, 27, 27, .978), rgba(4, 10, 13, .992));
  --market-gradient:
    radial-gradient(circle at 92% 10%, rgba(126, 242, 212, .085), transparent 38%),
    radial-gradient(circle at 5% 108%, rgba(105, 181, 255, .040), transparent 42%),
    linear-gradient(145deg, rgba(10, 29, 29, .985), rgba(4, 10, 13, .994));
  --dock-gradient:
    radial-gradient(circle at 8% 0%, rgba(126, 242, 212, .055), transparent 31%),
    radial-gradient(circle at 96% 100%, rgba(126, 103, 255, .038), transparent 36%),
    linear-gradient(120deg, rgba(9, 27, 27, .95), rgba(5, 12, 15, .95));
  --floating-surface: rgba(6, 18, 19, .982);
  --dialog-gradient: linear-gradient(145deg, #0b2322, #061113);
  --card-orb: rgba(126, 242, 212, .060);
  --card-orb-alt: rgba(125, 105, 255, .045);
  --card-inner-highlight: rgba(229, 255, 250, .044);
  --card-shadow-accent: rgba(78, 221, 190, .050);
  --shadow: 0 24px 68px rgba(0, 4, 7, .46), 0 10px 30px rgba(0, 63, 58, .105);
  --aurora-cyan: rgba(87, 231, 219, .125);
  --aurora-mint: rgba(107, 255, 190, .105);
  --aurora-violet: rgba(126, 100, 255, .085);
}
:root[data-theme="navy"] .market-card:where(:not(.app-shell, .app-shell *)){
  border-color: rgba(126, 242, 212, .18);
  box-shadow: var(--shadow), inset 0 1px 0 rgba(225,255,249,.045), 0 0 42px rgba(72, 220, 190, .025);
}
:root[data-theme="navy"] .wallet-mini.active:where(:not(.app-shell, .app-shell *)){
  border-color: rgba(126, 242, 212, .31);
  background:
    radial-gradient(circle at 88% 8%, rgba(126, 242, 212, .08), transparent 40%),
    color-mix(in srgb, var(--surface-strong) 94%, transparent);
}
/* NERO / OBSIDIAN: niente dominante blu. Nero vero + grafite + argento. */
:root[data-theme="black"]:where(:not(.app-shell, .app-shell *)){
  --bg: #000000;
  --surface: #050505;
  --surface-strong: #0a0a0b;
  --surface-soft: #111113;
  --line: rgba(255, 255, 255, .060);
  --line-strong: rgba(255, 255, 255, .125);
  --text: #f4f4f5;
  --muted: #77777d;
  --muted-strong: #b9b9be;
  --accent: #e3e5e8;
  --accent-ink: #050505;
  --accent-soft: rgba(235, 237, 240, .060);
  --page-gradient:
    radial-gradient(ellipse at 50% -22%, rgba(255, 255, 255, .035), transparent 34rem),
    linear-gradient(155deg, #050505 0%, #000000 52%, #030303 100%);
  --card-gradient:
    linear-gradient(145deg, rgba(15, 15, 16, .992), rgba(4, 4, 5, .997));
  --market-gradient:
    linear-gradient(145deg, rgba(18, 18, 19, .994), rgba(5, 5, 6, .998));
  --dock-gradient:
    linear-gradient(120deg, rgba(13, 13, 14, .975), rgba(4, 4, 5, .975));
  --floating-surface: rgba(7, 7, 8, .990);
  --dialog-gradient: linear-gradient(145deg, #111112, #050506);
  --card-orb: rgba(255, 255, 255, .022);
  --card-orb-alt: rgba(255, 255, 255, .012);
  --card-inner-highlight: rgba(255, 255, 255, .032);
  --card-shadow-accent: transparent;
  --shadow: 0 24px 64px rgba(0, 0, 0, .60), 0 8px 24px rgba(0, 0, 0, .34);
}
:root[data-theme="black"] body:where(:not(.app-shell, .app-shell *)){
  background: var(--page-gradient), #000;
}
/* Sul nero i glow delle card diventano quasi impercettibili e neutri. */
:root[data-theme="black"] .data-card:not(.market-card):where(:not(.app-shell, .app-shell *))::before,
:root[data-theme="black"] .market-card:where(:not(.app-shell, .app-shell *))::before{
  background: radial-gradient(circle at 50% 50%, rgba(255,255,255,.028), transparent 64%);
  opacity: .42;
}
:root[data-theme="black"] .data-card:where(:not(.app-shell, .app-shell *)),
:root[data-theme="black"] .wallet-dock:where(:not(.app-shell, .app-shell *)),
:root[data-theme="black"] .aggregate-strip:where(:not(.app-shell, .app-shell *)),
:root[data-theme="black"] .wallet-mini:where(:not(.app-shell, .app-shell *)){
  border-color: rgba(255, 255, 255, .070);
}
:root[data-theme="black"] .market-card:where(:not(.app-shell, .app-shell *)){
  border-color: rgba(255, 255, 255, .105);
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255,255,255,.038);
}
:root[data-theme="black"] .wallet-mini:where(:not(.app-shell, .app-shell *)){
  background: linear-gradient(145deg, rgba(12,12,13,.96), rgba(5,5,6,.98));
}
:root[data-theme="black"] .wallet-mini.active:where(:not(.app-shell, .app-shell *)){
  border-color: rgba(255,255,255,.20);
  background: linear-gradient(145deg, rgba(27,27,29,.98), rgba(9,9,10,.99));
  box-shadow: 0 0 0 1px rgba(255,255,255,.025), var(--shadow), inset 0 1px 0 rgba(255,255,255,.045);
}
:root[data-theme="black"] .apr-card:where(:not(.app-shell, .app-shell *)){
  border-color: rgba(255,255,255,.10);
  background: var(--card-gradient);
}
:root[data-theme="black"] .apr-card .metric-value:where(:not(.app-shell, .app-shell *)),
:root[data-theme="black"] .formula-pill:where(:not(.app-shell, .app-shell *)),
:root[data-theme="black"] .milestone-block strong:where(:not(.app-shell, .app-shell *)){
  color: #e6e7e9;
}
:root[data-theme="black"] .icon-button:hover:where(:not(.app-shell, .app-shell *)),
:root[data-theme="black"] .header-main-button:hover:where(:not(.app-shell, .app-shell *)),
:root[data-theme="black"] .menu-action:hover:where(:not(.app-shell, .app-shell *)){
  border-color: rgba(255,255,255,.14);
  background: #111113;
}
:root[data-theme="black"] .market-tf-track:where(:not(.app-shell, .app-shell *)){
  background: rgba(255,255,255,.075);
}
/* Swatch: differenza evidente già nel selettore. */
.theme-swatch.navy:where(:not(.app-shell, .app-shell *)){
  background:
    radial-gradient(circle at 74% 24%, rgba(113, 255, 206, .70), transparent 25%),
    radial-gradient(circle at 18% 80%, rgba(126, 101, 255, .50), transparent 34%),
    linear-gradient(145deg, #0b3940, #060816 72%);
}
.theme-swatch.black:where(:not(.app-shell, .app-shell *)){
  background:
    radial-gradient(circle at 70% 25%, rgba(255,255,255,.16), transparent 26%),
    linear-gradient(145deg, #18181a, #000000 74%);
  border-color: rgba(255,255,255,.14);
}
/* =========================================================
   v15.16 — TradingView full-screen chart
   ========================================================= */
.chart-dialog:where(:not(.app-shell, .app-shell *)){
  position: fixed;
  z-index: 220;
  inset: 0;
  width: 100vw;
  max-width: none;
  height: 100dvh;
  max-height: none;
  margin: 0;
  padding: 0;
  overflow: hidden;
  border: 0;
  border-radius: 0;
  background: var(--dialog-gradient);
  color: var(--text);
  box-shadow: none;
}
.chart-dialog:where(:not(.app-shell, .app-shell *))::backdrop{ background: rgba(1, 4, 12, .88); }
.chart-dialog-shell:where(:not(.app-shell, .app-shell *)){
  width: 100%;
  height: 100%;
  min-height: 0;
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
  padding: 0;
}
.chart-dialog-heading:where(:not(.app-shell, .app-shell *)){
  z-index: 3;
  min-height: 60px;
  align-items: center;
  padding: 9px clamp(12px, 2vw, 24px);
  border-bottom: 1px solid var(--line);
  background: color-mix(in srgb, var(--floating-surface) 94%, transparent);
  backdrop-filter: blur(18px);
}
.chart-dialog-heading h2:where(:not(.app-shell, .app-shell *)){ margin: 2px 0 0; font-size: clamp(1rem, 1.6vw, 1.25rem); }
.chart-dialog-heading small:where(:not(.app-shell, .app-shell *)){ display: block; margin-top: 1px; color: var(--muted); font-size: .62rem; font-weight: 700; letter-spacing: .05em; }
.chart-controls:where(:not(.app-shell, .app-shell *)){
  z-index: 3;
  display: flex;
  align-items: end;
  gap: 12px;
  padding: 8px clamp(12px, 2vw, 24px);
  overflow-x: auto;
  border-bottom: 1px solid var(--line);
  background: color-mix(in srgb, var(--surface) 92%, transparent);
  backdrop-filter: blur(16px);
  scrollbar-width: none;
}
.chart-controls:where(:not(.app-shell, .app-shell *))::-webkit-scrollbar{ display: none; }
.chart-control-group:where(:not(.app-shell, .app-shell *)){ min-width: max-content; display: grid; gap: 5px; }
.chart-control-group > span:where(:not(.app-shell, .app-shell *)){ color: var(--muted); font-size: .58rem; font-weight: 850; letter-spacing: .08em; text-transform: uppercase; }
.chart-interval-group:where(:not(.app-shell, .app-shell *)),
.chart-range-group:where(:not(.app-shell, .app-shell *)){ justify-items: start; }
.chart-segmented:where(:not(.app-shell, .app-shell *)){
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 3px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: color-mix(in srgb, var(--surface-strong) 78%, transparent);
}
.chart-segmented button:where(:not(.app-shell, .app-shell *)){
  min-width: 42px;
  min-height: 30px;
  padding: 0 9px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--muted-strong);
  font-size: .67rem;
  font-weight: 820;
  cursor: pointer;
  transition: background .16s ease, color .16s ease, box-shadow .16s ease, transform .12s ease;
}
.chart-segmented button:hover:where(:not(.app-shell, .app-shell *)){ color: var(--text); background: var(--surface-soft); }
.chart-segmented button:active:where(:not(.app-shell, .app-shell *)){ transform: scale(.96); }
.chart-segmented button.active:where(:not(.app-shell, .app-shell *)){
  background: color-mix(in srgb, var(--accent) 16%, var(--surface-soft));
  color: var(--text);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 34%, transparent), 0 4px 16px var(--accent-soft);
}
.tradingview-chart-host:where(:not(.app-shell, .app-shell *)){
  position: relative;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  border: 0;
  border-radius: 0;
  background: color-mix(in srgb, var(--surface) 98%, transparent);
}
.tradingview-chart-host .tradingview-widget-container:where(:not(.app-shell, .app-shell *)){ width: 100%; height: 100%; }
.tradingview-chart-host .tradingview-widget-container__widget:where(:not(.app-shell, .app-shell *)){ width: 100%; height: calc(100% - 26px); }
.tradingview-chart-host .tradingview-widget-copyright:where(:not(.app-shell, .app-shell *)){
  height: 26px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
  padding: 0 8px;
  color: var(--muted);
  background: color-mix(in srgb, var(--surface) 98%, transparent);
  font-size: .59rem;
}
.tradingview-chart-host .tradingview-widget-copyright a:where(:not(.app-shell, .app-shell *)){ color: var(--accent); text-decoration: none; }
.chart-placeholder:where(:not(.app-shell, .app-shell *)){ position: absolute; inset: 0; display: grid; place-content: center; justify-items: center; gap: 10px; color: var(--muted); font-size: .75rem; }
.chart-placeholder i:where(:not(.app-shell, .app-shell *)){ width: 22px; height: 22px; border: 2px solid var(--line-strong); border-top-color: var(--accent); border-radius: 50%; animation: spin .8s linear infinite; }
.chart-dialog-note:where(:not(.app-shell, .app-shell *)){ display: none; }
:root[data-theme="navy"] .chart-dialog:where(:not(.app-shell, .app-shell *)){ background: #071116; }
:root[data-theme="black"] .chart-dialog:where(:not(.app-shell, .app-shell *)){ background: #050506; }
:root[data-theme="light"] .chart-dialog:where(:not(.app-shell, .app-shell *)){ background: #f8fbff; }
:root[data-theme="light"] .chart-dialog:where(:not(.app-shell, .app-shell *))::backdrop{ background: rgba(20, 39, 58, .45); }
@media  (max-width: 760px) {.chart-dialog-heading:where(:not(.app-shell, .app-shell *)){ min-height: 54px; padding: 7px 10px; }
.chart-dialog-heading .card-label:where(:not(.app-shell, .app-shell *)){ display: none; }
.chart-controls:where(:not(.app-shell, .app-shell *)){ gap: 8px; padding: 7px 10px; }
.chart-control-group > span:where(:not(.app-shell, .app-shell *)){ font-size: .54rem; }
.chart-segmented button:where(:not(.app-shell, .app-shell *)){ min-width: 39px; min-height: 29px; padding: 0 8px; font-size: .64rem; }
.tradingview-chart-host .tradingview-widget-container__widget:where(:not(.app-shell, .app-shell *)){ height: calc(100% - 24px); }
.tradingview-chart-host .tradingview-widget-copyright:where(:not(.app-shell, .app-shell *)){ height: 24px; }}
/* v15.15 · Reward Tracker e Target Tracker collassabili */
.tracker-collapse-trigger:where(:not(.app-shell, .app-shell *)){
  min-width: 0;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  text-align: left;
  cursor: pointer;
}
.tracker-collapse-trigger > span:where(:not(.app-shell, .app-shell *)){ min-width: 0; display: block; }
.tracker-collapse-trigger .card-label:where(:not(.app-shell, .app-shell *)),
.tracker-collapse-trigger h2:where(:not(.app-shell, .app-shell *)){ pointer-events: none; }
.tracker-collapse-trigger svg:where(:not(.app-shell, .app-shell *)){
  width: 17px;
  height: 17px;
  flex: 0 0 auto;
  margin-top: 16px;
  color: var(--muted);
  transition: transform .24s ease, color .18s ease;
}
.tracker-collapse-trigger:hover svg:where(:not(.app-shell, .app-shell *)),
.tracker-collapse-trigger:focus-visible svg:where(:not(.app-shell, .app-shell *)){ color: var(--accent); }
.tracker-collapse-trigger:focus-visible:where(:not(.app-shell, .app-shell *)){
  outline: 0;
  border-radius: 8px;
  box-shadow: 0 0 0 3px var(--accent-soft);
}
.tracker-panel:where(:not(.app-shell, .app-shell *)){ overflow: visible; }
.tracker-panel[hidden]:where(:not(.app-shell, .app-shell *)){ display: none !important; }
.tracker-card.tracker-collapsed:where(:not(.app-shell, .app-shell *)){ min-height: 0; }
.tracker-card.tracker-collapsed .tracker-collapse-trigger svg:where(:not(.app-shell, .app-shell *)){ transform: rotate(-90deg); }
.tracker-card.tracker-collapsed .section-heading:where(:not(.app-shell, .app-shell *)){ align-items: center; }
.tracker-card.tracker-collapsed:where(:not(.app-shell, .app-shell *)){ padding-bottom: 18px; }
@media  (max-width: 620px) {.tracker-collapse-trigger:where(:not(.app-shell, .app-shell *)){ gap: 7px; }
.tracker-collapse-trigger svg:where(:not(.app-shell, .app-shell *)){ width: 15px; height: 15px; margin-top: 14px; }
.tracker-card.tracker-collapsed:where(:not(.app-shell, .app-shell *)){ padding-bottom: 15px; }}
@media  (prefers-reduced-motion: reduce) {.tracker-collapse-trigger svg:where(:not(.app-shell, .app-shell *)){ transition: none; }}
/* =========================================================
   v15.17 — Tema esteso a tutta l'interfaccia / viewport
   ========================================================= */
:root:where(:not(.app-shell, .app-shell *)){
  --theme-canvas: #030816;
  --theme-canvas-soft: #07152c;
  --theme-backdrop: rgba(1, 5, 16, .76);
}
:root[data-theme="navy"]:where(:not(.app-shell, .app-shell *)){
  --theme-canvas: #020708;
  --theme-canvas-soft: #071516;
  --theme-backdrop: rgba(0, 8, 10, .80);
}
:root[data-theme="black"]:where(:not(.app-shell, .app-shell *)){
  --theme-canvas: #000000;
  --theme-canvas-soft: #050505;
  --theme-backdrop: rgba(0, 0, 0, .88);
}
:root[data-theme="light"]:where(:not(.app-shell, .app-shell *)){
  --theme-canvas: #eef5ff;
  --theme-canvas-soft: #f8fbff;
  --theme-backdrop: rgba(33, 61, 88, .34);
}
/* Il canvas del tema copre anche rubber-band/overscroll e safe-area del browser. */
html:where(:not(.app-shell, .app-shell *)){
  min-height: 100%;
  background: var(--theme-canvas);
  background-color: var(--theme-canvas);
  overscroll-behavior-y: none;
}
body:where(:not(.app-shell, .app-shell *)){
  min-height: 100vh;
  min-height: 100dvh;
  background-color: var(--theme-canvas);
}
:root[data-theme="navy"] body:where(:not(.app-shell, .app-shell *)){
  background-color: var(--theme-canvas);
}
:root[data-theme="black"] body:where(:not(.app-shell, .app-shell *)){
  background: var(--page-gradient), var(--theme-canvas);
  background-color: var(--theme-canvas);
}
:root[data-theme="light"] body:where(:not(.app-shell, .app-shell *)){
  background: var(--page-gradient), var(--theme-canvas);
  background-color: var(--theme-canvas);
}
/* Header/footer partecipano al tema invece di apparire come zone trasparenti separate. */
.topbar:where(:not(.app-shell, .app-shell *)){
  background: color-mix(in srgb, var(--theme-canvas) 44%, transparent);
  backdrop-filter: blur(12px) saturate(1.04);
  -webkit-backdrop-filter: blur(12px) saturate(1.04);
}
footer:where(:not(.app-shell, .app-shell *)){
  background: linear-gradient(180deg, transparent, color-mix(in srgb, var(--theme-canvas) 56%, transparent));
}
/* Tutte le superfici flottanti usano la stessa famiglia cromatica del tema. */
.header-menu-panel:where(:not(.app-shell, .app-shell *)),
.header-search .search-panel:where(:not(.app-shell, .app-shell *)),
.theme-picker:where(:not(.app-shell, .app-shell *)),
.toast:where(:not(.app-shell, .app-shell *)),
.wallet-dialog:where(:not(.app-shell, .app-shell *)),
.chart-dialog:where(:not(.app-shell, .app-shell *)),
.chart-dialog-shell:where(:not(.app-shell, .app-shell *)),
.chart-dialog-heading:where(:not(.app-shell, .app-shell *)),
.chart-controls:where(:not(.app-shell, .app-shell *)),
.tradingview-chart-host:where(:not(.app-shell, .app-shell *)),
.tradingview-chart-host .tradingview-widget-copyright:where(:not(.app-shell, .app-shell *)){
  color-scheme: inherit;
}
.header-menu-panel:where(:not(.app-shell, .app-shell *)),
.header-search .search-panel:where(:not(.app-shell, .app-shell *)),
.theme-picker:where(:not(.app-shell, .app-shell *)),
.toast:where(:not(.app-shell, .app-shell *)){
  background-color: var(--theme-canvas-soft);
}
.wallet-dialog:where(:not(.app-shell, .app-shell *)){
  background: var(--dialog-gradient), var(--theme-canvas-soft);
  background-color: var(--theme-canvas-soft);
}
.wallet-dialog:where(:not(.app-shell, .app-shell *))::backdrop,
.chart-dialog:where(:not(.app-shell, .app-shell *))::backdrop{
  background: var(--theme-backdrop);
  backdrop-filter: blur(8px) saturate(.94);
  -webkit-backdrop-filter: blur(8px) saturate(.94);
}
/* Full-screen TradingView: nessuna fascia esterna può restare con il colore del browser/widget. */
.chart-dialog:where(:not(.app-shell, .app-shell *)),
.chart-dialog-shell:where(:not(.app-shell, .app-shell *)),
.tradingview-chart-host:where(:not(.app-shell, .app-shell *)),
.tradingview-chart-host .tradingview-widget-container:where(:not(.app-shell, .app-shell *)),
.tradingview-chart-host .tradingview-widget-container__widget:where(:not(.app-shell, .app-shell *)),
.tradingview-chart-host .tradingview-widget-copyright:where(:not(.app-shell, .app-shell *)),
.chart-placeholder:where(:not(.app-shell, .app-shell *)){
  background-color: var(--theme-canvas);
}
:root[data-theme="navy"] .chart-dialog:where(:not(.app-shell, .app-shell *)),
:root[data-theme="navy"] .chart-dialog-shell:where(:not(.app-shell, .app-shell *)),
:root[data-theme="navy"] .tradingview-chart-host:where(:not(.app-shell, .app-shell *)){
  background: #020708;
}
:root[data-theme="black"] .chart-dialog:where(:not(.app-shell, .app-shell *)),
:root[data-theme="black"] .chart-dialog-shell:where(:not(.app-shell, .app-shell *)),
:root[data-theme="black"] .tradingview-chart-host:where(:not(.app-shell, .app-shell *)){
  background: #000000;
}
:root[data-theme="light"] .chart-dialog:where(:not(.app-shell, .app-shell *)),
:root[data-theme="light"] .chart-dialog-shell:where(:not(.app-shell, .app-shell *)),
:root[data-theme="light"] .tradingview-chart-host:where(:not(.app-shell, .app-shell *)){
  background: #eef5ff;
}
/* I controlli del grafico restano chiaramente parte del tema corrente. */
.chart-dialog-heading:where(:not(.app-shell, .app-shell *)){
  background: color-mix(in srgb, var(--theme-canvas-soft) 96%, transparent);
}
.chart-controls:where(:not(.app-shell, .app-shell *)){
  background: color-mix(in srgb, var(--theme-canvas) 92%, var(--surface));
}
.tradingview-chart-host .tradingview-widget-copyright:where(:not(.app-shell, .app-shell *)){
  background: var(--theme-canvas);
  border-top: 1px solid color-mix(in srgb, var(--line) 72%, transparent);
}
/* Form e autofill: niente campi bianchi/gialli estranei al tema. */
input:where(:not(.app-shell, .app-shell *)),
button:where(:not(.app-shell, .app-shell *)),
dialog:where(:not(.app-shell, .app-shell *)){
  accent-color: var(--accent);
}
input:-webkit-autofill:where(:not(.app-shell, .app-shell *)),
input:-webkit-autofill:hover:where(:not(.app-shell, .app-shell *)),
input:-webkit-autofill:focus:where(:not(.app-shell, .app-shell *)){
  -webkit-text-fill-color: var(--text);
  -webkit-box-shadow: 0 0 0 1000px var(--surface-strong) inset;
  caret-color: var(--text);
  transition: background-color 9999s ease-out 0s;
}
/* Scrollbar coerente sui browser che la mostrano. */
*:where(:not(.app-shell, .app-shell *)){
  scrollbar-color: color-mix(in srgb, var(--line-strong) 80%, var(--muted)) var(--theme-canvas);
}
body:where(:not(.app-shell, .app-shell *))::-webkit-scrollbar,
.chart-controls:where(:not(.app-shell, .app-shell *))::-webkit-scrollbar{
  background: var(--theme-canvas);
}
body:where(:not(.app-shell, .app-shell *))::-webkit-scrollbar-thumb{
  background: color-mix(in srgb, var(--line-strong) 76%, var(--muted));
  border: 3px solid var(--theme-canvas);
  border-radius: 999px;
}
@supports  (padding: max(0px)) {body:where(:not(.app-shell, .app-shell *)){
    /* Il colore del canvas resta visibile anche nelle safe-area iOS. */
    padding-left: env(safe-area-inset-left, 0px);
    padding-right: env(safe-area-inset-right, 0px);
  }
.chart-dialog-heading:where(:not(.app-shell, .app-shell *)){
    padding-left: max(clamp(12px, 2vw, 24px), env(safe-area-inset-left));
    padding-right: max(clamp(12px, 2vw, 24px), env(safe-area-inset-right));
    padding-top: max(9px, env(safe-area-inset-top));
  }
.chart-controls:where(:not(.app-shell, .app-shell *)){
    padding-left: max(clamp(12px, 2vw, 24px), env(safe-area-inset-left));
    padding-right: max(clamp(12px, 2vw, 24px), env(safe-area-inset-right));
  }
.tradingview-chart-host .tradingview-widget-copyright:where(:not(.app-shell, .app-shell *)){
    padding-bottom: env(safe-area-inset-bottom, 0px);
  }}
@media  (max-width: 760px) {@supports  (padding: max(0px)) {.chart-dialog-heading:where(:not(.app-shell, .app-shell *)){
      padding-left: max(10px, env(safe-area-inset-left));
      padding-right: max(10px, env(safe-area-inset-right));
      padding-top: max(7px, env(safe-area-inset-top));
    }
.chart-controls:where(:not(.app-shell, .app-shell *)){
      padding-left: max(10px, env(safe-area-inset-left));
      padding-right: max(10px, env(safe-area-inset-right));
    }}}
/* =========================================================
   v15.18 — Wordmark header più presente e raffinato
   ========================================================= */
.header-title:where(:not(.app-shell, .app-shell *)){
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: clamp(8px, 1.05vw, 15px);
  min-width: 0;
  color: var(--text);
  font-size: clamp(1.08rem, 1.5vw, 1.34rem);
  line-height: 1;
  letter-spacing: -.035em;
  text-decoration: none;
}
.header-wordmark:where(:not(.app-shell, .app-shell *)){
  position: relative;
  display: inline-flex;
  align-items: baseline;
  gap: .28em;
  white-space: nowrap;
  filter: drop-shadow(0 5px 18px color-mix(in srgb, var(--accent) 10%, transparent));
}
.header-wordmark strong:where(:not(.app-shell, .app-shell *)){
  color: var(--text);
  font-size: 1.06em;
  font-weight: 920;
  letter-spacing: .045em;
}
.header-wordmark > span:where(:not(.app-shell, .app-shell *)){
  color: color-mix(in srgb, var(--text) 90%, var(--muted));
  font-weight: 665;
  letter-spacing: -.04em;
}
.header-title-rail:where(:not(.app-shell, .app-shell *)){
  position: relative;
  width: clamp(18px, 2.7vw, 38px);
  height: 8px;
  flex: 0 1 auto;
  opacity: .76;
}
.header-title-rail:where(:not(.app-shell, .app-shell *))::before,
.header-title-rail:where(:not(.app-shell, .app-shell *))::after,
.header-title-rail i:where(:not(.app-shell, .app-shell *)){
  position: absolute;
  top: 50%;
  content: "";
  transform: translateY(-50%);
}
.header-title-rail:where(:not(.app-shell, .app-shell *))::before{
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--accent) 62%, var(--line-strong)));
}
.header-title-rail-right:where(:not(.app-shell, .app-shell *))::before{
  background: linear-gradient(90deg, color-mix(in srgb, var(--accent) 62%, var(--line-strong)), transparent);
}
.header-title-rail i:where(:not(.app-shell, .app-shell *)){
  width: 4px;
  height: 4px;
  right: -1px;
  border: 1px solid color-mix(in srgb, var(--accent) 80%, var(--text));
  border-radius: 50%;
  background: color-mix(in srgb, var(--theme-canvas) 72%, transparent);
  box-shadow: 0 0 10px color-mix(in srgb, var(--accent) 34%, transparent);
}
.header-title-rail-right i:where(:not(.app-shell, .app-shell *)){
  right: auto;
  left: -1px;
}
.header-title-gem:where(:not(.app-shell, .app-shell *)){
  position: absolute;
  top: -7px;
  right: -7px;
  width: 5px;
  height: 5px;
  border: 1px solid color-mix(in srgb, var(--accent) 82%, var(--text));
  border-radius: 1px;
  background: color-mix(in srgb, var(--accent) 16%, transparent);
  box-shadow: 0 0 10px color-mix(in srgb, var(--accent) 24%, transparent);
  transform: rotate(45deg);
  opacity: .78;
}
/* Aurora: il wordmark prende un minimo di atmosfera senza diventare un neon. */
:root[data-theme="navy"] .header-wordmark strong:where(:not(.app-shell, .app-shell *)){
  background: linear-gradient(110deg, #f7fdff 20%, #a9f7ed 58%, #b9c8ff 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
/* Obsidian resta volutamente monocromatico. */
:root[data-theme="black"] .header-title-rail:where(:not(.app-shell, .app-shell *)),
:root[data-theme="black"] .header-title-gem:where(:not(.app-shell, .app-shell *)){
  opacity: .48;
}
:root[data-theme="black"] .header-wordmark:where(:not(.app-shell, .app-shell *)){
  filter: none;
}
/* Chiaro: riflesso appena più netto per mantenere contrasto. */
:root[data-theme="light"] .header-title-rail:where(:not(.app-shell, .app-shell *)){
  opacity: .58;
}
