/* =========================================================
   v15.33 — Boot splash / tagline + progress
   ========================================================= */
body.boot-loading:where(:not(.app-shell, .app-shell *)){
  overflow: hidden;
}
body.boot-loading .app-shell:where(:not(.app-shell, .app-shell *)){
  opacity: 0;
  transform: scale(.992);
}
.app-shell:where(:not(.app-shell, .app-shell *)){
  transition: opacity .46s ease, transform .58s cubic-bezier(.22,.7,.22,1);
}
.boot-splash:where(:not(.app-shell, .app-shell *)){
  position: fixed;
  z-index: 100000;
  inset: 0;
  min-width: 100vw;
  min-height: 100vh;
  min-height: 100dvh;
  display: grid;
  place-items: center;
  overflow: hidden;
  background: var(--page-gradient), var(--bg);
  color: var(--text);
  opacity: 1;
  visibility: visible;
  transition: opacity .52s ease, visibility .52s step-end;
  isolation: isolate;
}
.boot-splash:where(:not(.app-shell, .app-shell *))::before,
.boot-splash:where(:not(.app-shell, .app-shell *))::after{
  content: "";
  position: absolute;
  z-index: -1;
  width: min(70vw, 680px);
  aspect-ratio: 1;
  border-radius: 50%;
  pointer-events: none;
  filter: blur(70px);
  opacity: .16;
}
.boot-splash:where(:not(.app-shell, .app-shell *))::before{
  top: -24%;
  left: -18%;
  background: var(--accent);
}
.boot-splash:where(:not(.app-shell, .app-shell *))::after{
  right: -22%;
  bottom: -28%;
  background: color-mix(in srgb, var(--accent) 52%, #7b6cff 48%);
  opacity: .10;
}
.boot-splash.leaving:where(:not(.app-shell, .app-shell *)){
  opacity: 0;
  visibility: hidden;
}
.boot-splash-core:where(:not(.app-shell, .app-shell *)){
  position: relative;
  width: clamp(230px, 32vw, 330px);
  aspect-ratio: 1;
  display: grid;
  place-items: center;
  transform: translateZ(0);
}
.boot-ring:where(:not(.app-shell, .app-shell *)){
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
  transform: rotate(-90deg) translateZ(0);
}
.boot-ring-track:where(:not(.app-shell, .app-shell *)),
.boot-ring-progress:where(:not(.app-shell, .app-shell *)){
  vector-effect: non-scaling-stroke;
  stroke-width: 1.2;
}
.boot-ring-track:where(:not(.app-shell, .app-shell *)){
  stroke: color-mix(in srgb, var(--line-strong) 60%, transparent);
  opacity: .13;
}
.boot-ring-progress:where(:not(.app-shell, .app-shell *)){
  stroke: var(--accent);
  stroke-width: 2.25;
  stroke-dasharray: 100;
  stroke-dashoffset: 100;
  stroke-linecap: round;
  opacity: 0;
  filter: drop-shadow(0 0 7px color-mix(in srgb, var(--accent) 34%, transparent));
  animation: boot-ring-draw 2.18s cubic-bezier(.2,.72,.24,1) .28s forwards;
}
.boot-copy:where(:not(.app-shell, .app-shell *)){
  position: relative;
  z-index: 1;
  width: 72%;
  display: grid;
  justify-items: center;
  gap: 10px;
  text-align: center;
}
.boot-wordmark:where(:not(.app-shell, .app-shell *)){
  display: inline-flex;
  align-items: baseline;
  gap: .28em;
  color: var(--text);
  font-size: clamp(1.7rem, 4vw, 2.45rem);
  letter-spacing: -.055em;
  white-space: nowrap;
  opacity: 0;
  transform: translateY(7px) scale(.985);
  animation: boot-wordmark-in .72s cubic-bezier(.2,.76,.28,1) .12s forwards;
}
.boot-wordmark strong:where(:not(.app-shell, .app-shell *)){
  font-weight: 900;
  letter-spacing: -.07em;
}
.boot-wordmark span:where(:not(.app-shell, .app-shell *)){
  color: var(--muted-strong);
  font-weight: 650;
  letter-spacing: -.045em;
}
.boot-tagline:where(:not(.app-shell, .app-shell *)){
  max-width: 100%;
  overflow: hidden;
  color: color-mix(in srgb, var(--muted-strong) 82%, var(--accent) 18%);
  font-size: clamp(.52rem, 1.25vw, .68rem);
  font-weight: 800;
  letter-spacing: .21em;
  line-height: 1.2;
  white-space: nowrap;
  opacity: 0;
  clip-path: inset(0 100% 0 0);
  transform: translateY(3px);
  animation: boot-tagline-write 1.38s cubic-bezier(.2,.72,.26,1) .62s forwards;
}
.boot-tagline span:where(:not(.app-shell, .app-shell *)){
  display: inline-block;
  padding-left: .21em;
}
.boot-percent:where(:not(.app-shell, .app-shell *)){
  min-width: 4.1ch;
  color: color-mix(in srgb, var(--muted) 82%, var(--accent) 18%);
  font-size: clamp(.48rem, 1vw, .61rem);
  font-weight: 800;
  letter-spacing: .13em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  opacity: 0;
  transform: translateY(2px);
  animation: boot-percent-in .35s ease .34s forwards;
}
.boot-splash.leaving .boot-splash-core:where(:not(.app-shell, .app-shell *)){
  animation: boot-core-out .48s cubic-bezier(.4,0,.8,.2) forwards;
}
@keyframes boot-ring-draw {
  0% { stroke-dashoffset: 100; opacity: 0; }
  8% { opacity: .42; }
  78% { opacity: .9; }
  100% { stroke-dashoffset: 0; opacity: 1; }
}
@keyframes boot-wordmark-in {
  to { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes boot-tagline-write {
  0% { opacity: 0; clip-path: inset(0 100% 0 0); transform: translateY(3px); }
  12% { opacity: .48; }
  100% { opacity: 1; clip-path: inset(0 0 0 0); transform: translateY(0); }
}
@keyframes boot-percent-in {
  to { opacity: .72; transform: translateY(0); }
}
@keyframes boot-core-out {
  to { opacity: 0; transform: scale(1.025); filter: blur(2px); }
}
