:root[data-theme="light"] .boot-splash:where(:not(.app-shell, .app-shell *))::after{ opacity: .08; }
@media  (max-width: 600px) {.boot-splash-core:where(:not(.app-shell, .app-shell *)){ width: min(72vw, 300px); }
.boot-copy:where(:not(.app-shell, .app-shell *)){ width: 76%; gap: 9px; }
.boot-wordmark:where(:not(.app-shell, .app-shell *)){ font-size: clamp(1.6rem, 7vw, 2.05rem); }
.boot-tagline:where(:not(.app-shell, .app-shell *)){ font-size: clamp(.48rem, 2.45vw, .61rem); letter-spacing: .17em; }
