/* =========================================================
   v15.98.97 — subdued, theme-native section labels
   Same theme family, less saturation/contrast; cascade becomes a soft sheen.
   ========================================================= */
:root[data-theme="navy"]:where(:not(.app-shell, .app-shell *)){
  --section-overview:color-mix(in srgb,var(--accent) 72%,var(--muted-strong) 28%);
  --section-wallet:color-mix(in srgb,var(--accent) 54%,var(--muted-strong) 46%);
  --section-staking:color-mix(in srgb,var(--accent) 62%,var(--muted) 38%);
  --section-market:color-mix(in srgb,var(--accent) 46%,var(--muted-strong) 54%);
  --section-delegations:color-mix(in srgb,var(--accent) 58%,var(--muted-strong) 42%);
}
:root[data-theme="black"]:where(:not(.app-shell, .app-shell *)){
  --section-overview:color-mix(in srgb,var(--accent) 70%,var(--muted) 30%);
  --section-wallet:color-mix(in srgb,var(--accent) 56%,var(--muted) 44%);
  --section-staking:color-mix(in srgb,var(--accent) 62%,var(--muted-strong) 38%);
  --section-market:color-mix(in srgb,var(--accent) 48%,var(--muted) 52%);
  --section-delegations:color-mix(in srgb,var(--accent) 58%,var(--muted) 42%);
}
:root[data-theme="light"]:where(:not(.app-shell, .app-shell *)){
  --section-overview:color-mix(in srgb,var(--accent) 72%,var(--muted-strong) 28%);
  --section-wallet:color-mix(in srgb,var(--accent) 58%,var(--muted-strong) 42%);
  --section-staking:color-mix(in srgb,var(--accent) 64%,var(--muted) 36%);
  --section-market:color-mix(in srgb,var(--accent) 50%,var(--muted-strong) 50%);
  --section-delegations:color-mix(in srgb,var(--accent) 60%,var(--muted-strong) 40%);
}
:root[data-theme="amber"]:where(:not(.app-shell, .app-shell *)){
  --section-overview:color-mix(in srgb,var(--accent) 68%,var(--muted-strong) 32%);
  --section-wallet:color-mix(in srgb,var(--accent) 56%,var(--muted) 44%);
  --section-staking:color-mix(in srgb,var(--accent) 62%,var(--muted-strong) 38%);
  --section-market:color-mix(in srgb,var(--accent) 74%,var(--muted-strong) 26%);
