  opacity:.72 !important;
}
@keyframes dashboardSectionCascade{
  0%,100%{opacity:.68;filter:brightness(1);text-shadow:0 0 0 transparent;}
  1.6%{opacity:.90;filter:brightness(1.08);text-shadow:0 0 4px color-mix(in srgb,var(--section-accent,var(--accent)) 28%,transparent),0 0 9px color-mix(in srgb,var(--section-accent,var(--accent)) 12%,transparent);}
  3.8%{opacity:.78;filter:brightness(1.03);text-shadow:0 0 2px color-mix(in srgb,var(--section-accent,var(--accent)) 14%,transparent);}
  6.2%{opacity:.68;filter:brightness(1);text-shadow:0 0 0 transparent;}
}
/* Dashboard styles from the supplied donor version. */
:root:where(.app-shell, .app-shell *){
  color-scheme: dark;
  --bg: #030816;
  --surface: #07152c;
  --surface-strong: #0b1d3c;
  --surface-soft: #10294e;
  --line: rgba(151, 200, 255, .11);
  --line-strong: rgba(151, 200, 255, .21);
  --text: #f5f9ff;
  --muted: #8192ac;
  --muted-strong: #b5c4d9;
  --accent: #48d7ff;
  --accent-ink: #001820;
  --accent-soft: rgba(72, 215, 255, .14);
  --page-gradient: radial-gradient(circle at 12% -10%, rgba(27, 112, 255, .36), transparent 34rem), radial-gradient(circle at 88% 4%, rgba(36, 214, 255, .17), transparent 31rem), linear-gradient(145deg, #071735 0%, #030816 48%, #06122b 100%);
  --card-gradient: linear-gradient(145deg, rgba(13, 34, 69, .96), rgba(5, 17, 39, .96));
  --market-gradient: radial-gradient(circle at 88% 18%, rgba(72, 215, 255, .17), transparent 45%), linear-gradient(135deg, #0d2854 0%, #07172f 58%, #061126 100%);
  --dock-gradient: linear-gradient(120deg, rgba(13, 34, 69, .88), rgba(6, 20, 44, .84));
  --floating-surface: rgba(7, 21, 44, .97);
  --dialog-gradient: linear-gradient(145deg, #0d2347, #06142d);
  --up: #39e58c;
  --up-soft: rgba(57, 229, 140, .15);
  --down: #ff5f70;
  --down-soft: rgba(255, 95, 112, .15);
  --radius: 18px;
  --shadow: 0 24px 65px rgba(0, 4, 18, .36);
  font-family: Inter, ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}
:root[data-theme="black"]:where(.app-shell, .app-shell *){
  --bg: #030405;
  --surface: #090c11;
  --surface-strong: #10151d;
  --surface-soft: #181f2a;
  --line: rgba(255, 255, 255, .09);
  --line-strong: rgba(255, 255, 255, .17);
  --text: #f7f9fc;
  --muted: #7f8997;
  --muted-strong: #b7bfca;
  --accent: #5ce1ff;
  --accent-ink: #00181d;
  --accent-soft: rgba(92, 225, 255, .11);
  --page-gradient: radial-gradient(circle at 50% -18%, rgba(28, 75, 102, .30), transparent 35rem), linear-gradient(145deg, #090d13 0%, #030405 58%, #080b10 100%);
  --card-gradient: linear-gradient(145deg, rgba(16, 21, 29, .98), rgba(7, 10, 15, .98));
  --market-gradient: radial-gradient(circle at 88% 18%, rgba(92, 225, 255, .12), transparent 45%), linear-gradient(135deg, #141c28 0%, #090d14 70%);
  --dock-gradient: linear-gradient(120deg, rgba(18, 24, 33, .94), rgba(8, 11, 16, .92));
  --floating-surface: rgba(10, 14, 21, .98);
  --dialog-gradient: linear-gradient(145deg, #121923, #080b11);
}
:root[data-theme="light"]:where(.app-shell, .app-shell *){
  color-scheme: light;
  --bg: #eef5ff;
  --surface: #ffffff;
  --surface-strong: #f5f9ff;
  --surface-soft: #e8f1fb;
  --line: rgba(17, 53, 91, .10);
  --line-strong: rgba(17, 53, 91, .20);
  --text: #10233b;
  --muted: #657991;
  --muted-strong: #41566f;
  --accent: #007da5;
  --accent-ink: #ffffff;
  --accent-soft: rgba(0, 125, 165, .10);
  --up: #087d4c;
  --up-soft: rgba(8, 125, 76, .12);
  --down: #d33d50;
  --down-soft: rgba(211, 61, 80, .11);
  --page-gradient: radial-gradient(circle at 12% -8%, rgba(64, 161, 255, .20), transparent 34rem), radial-gradient(circle at 88% 2%, rgba(0, 193, 226, .12), transparent 30rem), linear-gradient(145deg, #f8fbff 0%, #edf5ff 52%, #f5faff 100%);
  --card-gradient: linear-gradient(145deg, rgba(255, 255, 255, .98), rgba(244, 249, 255, .98));
  --market-gradient: radial-gradient(circle at 88% 18%, rgba(0, 161, 203, .13), transparent 45%), linear-gradient(135deg, #ffffff 0%, #edf7ff 68%, #f8fbff 100%);
  --dock-gradient: linear-gradient(120deg, rgba(255, 255, 255, .94), rgba(239, 247, 255, .92));
  --floating-surface: rgba(255, 255, 255, .98);
  --dialog-gradient: linear-gradient(145deg, #ffffff, #eff7ff);
  --shadow: 0 22px 58px rgba(32, 75, 120, .12);
}
*:where(.app-shell, .app-shell *){ box-sizing: border-box; }
html:where(.app-shell, .app-shell *){ scroll-behavior: smooth; }
body:where(.app-shell, .app-shell *){
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background: var(--page-gradient), var(--bg);
  background-attachment: fixed;
  color: var(--text);
  font-size: 16px;
  line-height: 1.5;
}
button:where(.app-shell, .app-shell *),
input:where(.app-shell, .app-shell *){ font: inherit; }
button:where(.app-shell, .app-shell *){ color: inherit; }
button:where(.app-shell, .app-shell *),
a:where(.app-shell, .app-shell *){ -webkit-tap-highlight-color: transparent; }
svg:where(.app-shell, .app-shell *){ display: block; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.app-shell:where(.app-shell, .app-shell *){ width: min(1600px, calc(100% - clamp(20px, 3vw, 52px))); margin: 0 auto; }
.topbar:where(.app-shell, .app-shell *){
  position: relative;
  z-index: 10;
  min-height: 78px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  border-bottom: 1px solid var(--line);
}
.brand:where(.app-shell, .app-shell *){ display: inline-flex; align-items: center; gap: 11px; color: var(--text); text-decoration: none; font-size: 1rem; letter-spacing: -.02em; }
.brand strong:where(.app-shell, .app-shell *){ font-weight: 800; }
.brand-mark:where(.app-shell, .app-shell *){
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: var(--accent);
  color: var(--accent-ink);
  font-weight: 900;
  box-shadow: 0 0 24px var(--accent-soft);
}
.topbar-tools:where(.app-shell, .app-shell *){ display: grid; justify-items: end; gap: 4px; padding: 9px 0 7px; }
.topbar-actions:where(.app-shell, .app-shell *){ display: flex; align-items: center; gap: 8px; }
.header-updated:where(.app-shell, .app-shell *){ color: var(--muted); font-size: .62rem; font-weight: 650; letter-spacing: .02em; }
.header-updated b:where(.app-shell, .app-shell *){ color: var(--muted-strong); font-weight: 750; font-variant-numeric: tabular-nums; }
.connection:where(.app-shell, .app-shell *){
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 38px;
  padding: 0 13px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--muted-strong);
  font-size: .78rem;
  font-weight: 700;
}
.connection i:where(.app-shell, .app-shell *),
.live-tag i:where(.app-shell, .app-shell *){ width: 7px; height: 7px; border-radius: 50%; background: #f0aa39; box-shadow: 0 0 0 4px rgba(240, 170, 57, .12); }
.connection.online i:where(.app-shell, .app-shell *),
.live-tag i:where(.app-shell, .app-shell *){ background: var(--up); box-shadow: 0 0 0 4px var(--up-soft); }
.connection.offline i:where(.app-shell, .app-shell *){ background: var(--down); box-shadow: 0 0 0 4px var(--down-soft); }
.icon-button:where(.app-shell, .app-shell *){
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--surface);
  cursor: pointer;
  transition: border-color .2s, background .2s, transform .2s;
}
.icon-button svg:where(.app-shell, .app-shell *){ width: 18px; }
.icon-button:hover:where(.app-shell, .app-shell *){ border-color: var(--line-strong); background: var(--surface-soft); }
.icon-button:active:where(.app-shell, .app-shell *){ transform: scale(.95); }
#themeButton:where(.app-shell, .app-shell *){ position: relative; }
#themeButton:where(.app-shell, .app-shell *)::after{ content: ""; position: absolute; right: 5px; bottom: 5px; width: 6px; height: 6px; border: 1px solid var(--surface); border-radius: 50%; background: #3aa9ff; box-shadow: 0 0 7px rgba(58,169,255,.75); }
#themeButton[data-theme="black"]:where(.app-shell, .app-shell *)::after{ background: #8792a2; box-shadow: 0 0 7px rgba(255,255,255,.35); }
#themeButton[data-theme="light"]:where(.app-shell, .app-shell *)::after{ background: #ffffff; border-color: #7c8da2; box-shadow: 0 0 7px rgba(36,116,180,.35); }
.theme-control:where(.app-shell, .app-shell *){ position: relative; }
.theme-picker:where(.app-shell, .app-shell *){
  position: absolute;
  z-index: 12;
  top: calc(100% + 12px);
  right: 0;
  width: 168px;
  display: grid;
  gap: 5px;
  padding: 8px;
  border: 1px solid var(--line-strong);
  border-radius: 13px;
  background: var(--floating-surface);
  box-shadow: 0 22px 55px rgba(0, 4, 18, .38);
  opacity: 0;
  pointer-events: none;
  transform: translateY(-8px) scale(.98);
  transform-origin: top right;
  transition: opacity .18s, transform .18s;
  backdrop-filter: blur(18px);
}
.theme-control.open .theme-picker:where(.app-shell, .app-shell *){ opacity: 1; pointer-events: auto; transform: translateY(0) scale(1); }
.theme-picker button:where(.app-shell, .app-shell *){ display: grid; grid-template-columns: 24px 1fr; align-items: center; gap: 9px; min-height: 39px; padding: 0 9px; border: 1px solid transparent; border-radius: 9px; background: transparent; color: var(--muted-strong); text-align: left; font-size: .76rem; font-weight: 750; cursor: pointer; }
.theme-picker button:hover:where(.app-shell, .app-shell *),
.theme-picker button.active:where(.app-shell, .app-shell *){ border-color: var(--line); background: var(--surface-soft); color: var(--text); }
.theme-swatch:where(.app-shell, .app-shell *){ width: 23px; height: 23px; border: 1px solid rgba(255,255,255,.18); border-radius: 7px; }
.theme-swatch.navy:where(.app-shell, .app-shell *){ background: linear-gradient(145deg, #1762bd, #06142d); }
.theme-swatch.black:where(.app-shell, .app-shell *){ background: linear-gradient(145deg, #29313d, #050607); }
.theme-swatch.light:where(.app-shell, .app-shell *){ border-color: rgba(17,53,91,.16); background: linear-gradient(145deg, #ffffff, #d9edff); }
.header-search:where(.app-shell, .app-shell *){ position: relative; display: flex; align-items: center; }
