}
.aggregate-strip.collapsed .aggregate-heading small:where(.app-shell, .app-shell *){
  margin-top: 2px;
}
@media  (max-width: 560px) {.aggregate-strip.collapsed .aggregate-heading:where(.app-shell, .app-shell *){
    min-height: 48px !important;
