.header-menu.open #menuButton:where(.app-shell, .app-shell *){ color: var(--accent); border-color: color-mix(in srgb, var(--accent) 34%, var(--line)); background: var(--accent-soft); }
.header-status-dot.connection:where(.app-shell, .app-shell *){
