:root[data-theme="navy"] body:where(.app-shell, .app-shell *)::before,
:root[data-theme="navy"] body:where(.app-shell, .app-shell *)::after{
  content: "";
  position: fixed;
  z-index: -1;
  inset: -22vmax;
  pointer-events: none;
  will-change: transform, opacity;
  transform: translate3d(0, 0, 0);
  backface-visibility: hidden;
