  background:
    radial-gradient(ellipse 34% 24% at 24% 28%, var(--aurora-cyan), transparent 72%),
    radial-gradient(ellipse 30% 25% at 70% 18%, var(--aurora-mint), transparent 72%),
    radial-gradient(ellipse 31% 27% at 73% 76%, var(--aurora-violet), transparent 74%);
