.owned-total-difference:where(.app-shell, .app-shell *){ padding-left: 6px; gap: 4px; }
.owned-total-plus:where(.app-shell, .app-shell *){ font-size: .94rem; }
.owned-total-difference > strong:where(.app-shell, .app-shell *){ font-size: .82rem; }}
/* v15.12 — prezzo medio e PnL */
.menu-average-price:where(.app-shell, .app-shell *){
