   ========================================================= */
.market-terminal-section:where(.app-shell, .app-shell *){
  width: 100%;
  margin-top: clamp(18px, 2vw, 26px);
}
.market-terminal-card:where(.app-shell, .app-shell *){
  width: 100%;
  overflow: hidden;
  padding: 0;
  border-color: color-mix(in srgb, var(--line-strong) 72%, transparent);
  background: color-mix(in srgb, var(--surface) 97%, transparent);
}
.market-terminal-header:where(.app-shell, .app-shell *){
  min-height: 82px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto 38px;
  align-items: center;
  gap: clamp(12px, 1.8vw, 22px);
  padding: 15px clamp(15px, 2vw, 24px);
  border-bottom: 1px solid var(--line);
  background:
    radial-gradient(circle at 9% 0%, color-mix(in srgb, var(--accent) 9%, transparent), transparent 36%),
    color-mix(in srgb, var(--surface-strong) 74%, transparent);
}
.market-terminal-identity:where(.app-shell, .app-shell *){ min-width: 0; }
.market-terminal-kicker:where(.app-shell, .app-shell *){
  display: block;
  margin-bottom: 2px;
  color: var(--muted);
  font-size: .59rem;
  font-weight: 850;
  letter-spacing: .13em;
  text-transform: uppercase;
}
.market-terminal-title-row:where(.app-shell, .app-shell *){
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
}
.market-terminal-title-row h2:where(.app-shell, .app-shell *){
  margin: 0;
  font-size: clamp(1.08rem, 1.8vw, 1.42rem);
  line-height: 1.1;
  letter-spacing: -.035em;
}
.market-terminal-live:where(.app-shell, .app-shell *){
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 21px;
  padding: 0 7px;
  border: 1px solid color-mix(in srgb, var(--up) 28%, var(--line));
  border-radius: 999px;
  color: var(--up);
  background: color-mix(in srgb, var(--up-soft) 72%, transparent);
  font-size: .54rem;
  font-weight: 900;
  letter-spacing: .08em;
}
.market-terminal-live i:where(.app-shell, .app-shell *){
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--up);
  box-shadow: 0 0 9px color-mix(in srgb, var(--up) 65%, transparent);
}
.market-terminal-quote:where(.app-shell, .app-shell *){
  min-width: 118px;
  display: grid;
  justify-items: end;
  gap: 2px;
  font-variant-numeric: tabular-nums;
}
.market-terminal-quote strong:where(.app-shell, .app-shell *){
  color: var(--text);
  font-size: clamp(1.12rem, 2vw, 1.55rem);
  line-height: 1;
  letter-spacing: -.045em;
}
.market-terminal-quote span:where(.app-shell, .app-shell *){
  min-height: 20px;
  display: inline-flex;
  align-items: center;
  padding: 0 7px;
  border-radius: 7px;
  font-size: .66rem;
