}
.market-terminal-quote span.positive:where(.app-shell, .app-shell *){ color: var(--up); background: var(--up-soft); }
.market-terminal-quote span.negative:where(.app-shell, .app-shell *){ color: var(--down); background: var(--down-soft); }
.market-terminal-quote span.neutral:where(.app-shell, .app-shell *){ color: var(--muted); background: var(--surface-soft); }
.market-terminal-collapse:where(.app-shell, .app-shell *){
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: color-mix(in srgb, var(--surface-soft) 72%, transparent);
  color: var(--muted-strong);
  cursor: pointer;
}
.market-terminal-collapse:hover:where(.app-shell, .app-shell *){ border-color: var(--line-strong); color: var(--text); }
.market-terminal-collapse svg:where(.app-shell, .app-shell *){ width: 17px; transition: transform .22s ease; }
