  grid-template-columns: repeat(6, minmax(0, 1fr));
}
.market-terminal-timeframes button:where(.app-shell, .app-shell *){
  min-width: 0 !important;
  width: 100%;
  min-height: 32px;
  padding-inline: 7px;
}
.market-terminal-view:where(.app-shell, .app-shell *){ flex: 0 0 auto; }
.market-terminal-view button:where(.app-shell, .app-shell *){
